NAME = 'KLV: Klingon Language Version of the World English Bible'
BOOK = 'Joshua'

CHAPTERS = {
    1: {
        1: "DaH 'oH qaSta' after the Hegh vo' Moses the toy'wI' vo' joH'a', vetlh joH'a' jatlhta' Daq Joshua the puqloD vo' Nun, Moses' toy'wI', ja'ta',",
        2: "“Moses wIj toy'wI' ghaH Heghpu'; DaH vaj Hu', jaH Dung vam Jordan, SoH, je Hoch vam ghotpu, Daq the puH nuq jIH nob Daq chaH, 'ach Daq the puqpu' vo' Israel.",
        3: "jIH ghaj nobpu' SoH Hoch Daq vetlh the bem vo' lIj qam DichDaq yIt Daq, as jIH ja'ta' Moses.",
        4: "vo' the ngem, je vam Lebanon, 'ach Daq the Dun bIQtIQ, the bIQtIQ Euphrates, Hoch the puH vo' the Hittites, je Daq the Dun biQ'a' toward the ghoS bIng vo' the pemHov, DIchDaq taH lIj veH.",
        5: "ghobe' loD DichDaq taH laH Daq Qam qaSpa' SoH Hoch the jajmey vo' lIj yIn. As jIH ghaHta' tlhej Moses, vaj jIH DichDaq taH tlhej SoH. jIH DichDaq ghobe' fail SoH ghobe' lon SoH.",
        6: "“taH HoS je vo' QaQ courage; vaD SoH DIchDaq cause vam ghotpu Daq inherit the puH nuq jIH swore Daq chaj vavpu' Daq nob chaH.",
        7: "neH taH HoS je very courageous, Daq observe Daq ta' according Daq Hoch the chut, nuq Moses wIj toy'wI' ra'ta' SoH. yImev tlhe' vo' 'oH Daq the nIH ghop joq Daq the poS, vetlh SoH may ghaj QaQ success wherever SoH jaH.",
        8: "vam paq vo' the chut DIchDaq ghobe' mej pa' vo' lIj nujDu', 'ach SoH DIchDaq ja''eghqa' Daq 'oH jaj je ram, vetlh SoH may observe Daq ta' according Daq Hoch vetlh ghaH ghItlhta' therein: vaD vaj SoH DIchDaq chenmoH lIj way mIp, je vaj SoH DIchDaq ghaj QaQ success.",
        9: "ghajbe' jIH ra'ta' SoH? taH HoS je vo' QaQ courage. yImev taH vIp, ghobe' taH dismayed: vaD joH'a' lIj joH'a' ghaH tlhej SoH wherever SoH jaH.”",
        10: "vaj Joshua ra'ta' the officers vo' the ghotpu, ja'ta',",
        11: "“juS vegh the midst vo' the raQ, je ra'ta'ghach mu'mey the ghotpu, ja'ta', ‘ghuH Soj; vaD within wej jajmey SoH 'oH Daq juS Dung vam Jordan, Daq jaH Daq Daq ghaj the puH, nuq joH'a' lIj joH'a' nob SoH Daq ghaj 'oH.'”",
        12: "Joshua jatlhta' Daq the Reubenites, je Daq the Gadites, je Daq the bID- tuq vo' Manasseh, ja'ta',",
        13: "“qaw the mu' nuq Moses the toy'wI' vo' joH'a' ra'ta' SoH, ja'ta', ‘joH'a' lIj joH'a' nob SoH leS, je DichDaq nob SoH vam puH.",
        14: "lIj be'nalpu', lIj mach ones, je lIj livestock, DIchDaq yIn Daq the puH nuq Moses nobta' SoH beyond the Jordan; 'ach SoH DIchDaq juS Dung qaSpa' lIj loDnI'pu' armed, Hoch the HoS loDpu' vo' valor, je DIchDaq QaH chaH",
        15: "until joH'a' ghajtaH nobpu' lIj loDnI'pu' leS, as ghaH ghajtaH nobpu' SoH, je chaH ghaj je possessed the puH nuq joH'a' lIj joH'a' nob chaH. vaj SoH DIchDaq chegh Daq the puH vo' lIj possession, je ghaj 'oH, nuq Moses the toy'wI' vo' joH'a' nobta' SoH beyond the Jordan toward the sunrise.'”",
        16: "chaH jangta' Joshua, ja'ta', “Hoch vetlh SoH ghaj ra'ta' maH maH DichDaq ta', je wherever SoH ngeH maH maH DichDaq jaH.",
        17: "Just as maH listened Daq Moses Daq Hoch Dochmey, vaj DichDaq maH 'Ij Daq SoH. neH may joH'a' lIj joH'a' taH tlhej SoH, as ghaH ghaHta' tlhej Moses.",
        18: "'Iv rebels Daq lIj ra'ta'ghach mu', je ta' taH' 'Ij Daq lIj mu'mey Daq Hoch vetlh SoH ra'ta'ghach mu'mey ghaH, ghaH DIchDaq be lan Daq Hegh. neH taH HoS je vo' QaQ courage.”",
    },
    2: {
        1: "Joshua the puqloD vo' Nun secretly ngeHta' cha' loDpu' pa' vo' Shittim as spies, ja'ta', “jaH, view the puH, including Jericho.” chaH mejta' je ghoSta' Daq the tuq vo' a naybe'wI' 'Iv pong ghaHta' Rahab, je Qongta' pa'.",
        2: "The joH vo' Jericho ghaHta' ja'ta', “yIlegh, loDpu' vo' the puqpu' vo' Israel ghoSta' Daq naDev tonight Daq spy pa' the puH.”",
        3: "The joH vo' Jericho ngeHta' Daq Rahab, ja'ta', “qem pa' the loDpu' 'Iv ghaj ghoS Daq SoH, 'Iv ghaj 'elta' Daq lIj tuq; vaD chaH ghaj ghoS Daq spy pa' Hoch the puH.”",
        4: "The be' tlhapta' the cha' loDpu' je hid chaH. vaj ghaH ja'ta', “HIja', the loDpu' ghoSta' Daq jIH, 'ach jIH ta'be' Sov nuqDaq chaH ghoSta' vo'.",
        5: "'oH qaSta' about the poH vo' the shutting vo' the lojmIt, ghorgh 'oH ghaHta' dark, vetlh the loDpu' mejta' pa'. nuqDaq the loDpu' mejta', jIH yImev Sov. Pursue chaH quickly; vaD SoH DichDaq overtake chaH.”",
        6: "'ach ghaH ghajta' qempu' chaH Dung Daq the roof, je hid chaH tlhej the stalks vo' flax, nuq ghaH ghajta' laid Daq order Daq the roof.",
        7: "The loDpu' pursued chaH the way Daq the Jordan Daq the fords: je as soon as chaH 'Iv pursued chaH ghajta' ghoSta' pa', chaH shut the lojmIt.",
        8: "qaSpa' chaH ghajta' laid bIng, ghaH ghoSta' Dung Daq chaH Daq the roof;",
        9: "je ghaH ja'ta' Daq the loDpu', “jIH Sov vetlh joH'a' ghajtaH nobpu' SoH the puH, je vetlh the taHvIp vo' SoH ghajtaH fallen Daq maH, je vetlh Hoch the nganpu' vo' the puH melt DoH qaSpa' SoH.",
        10: "vaD maH ghaj Qoyta' chay' joH'a' dried Dung the bIQ vo' the Doq biQ'a' { Note: joq, biQ'a' vo' Reeds } qaSpa' SoH, ghorgh SoH ghoSta' pa' vo' Egypt; je nuq SoH ta'ta' Daq the cha' joHpu' vo' the Amorites, 'Iv were beyond the Jordan, Daq Sihon je Daq Og, 'Iv SoH utterly Qaw'ta'.",
        11: "As soon as maH ghajta' Qoyta' 'oH, maj tIQDu' melted, ghobe' ta'ta' pa' remain vay' latlh qa' Daq vay' loD, because vo' SoH: vaD joH'a' lIj joH'a', ghaH ghaH joH'a' Daq chal Dung, je Daq tera' bIng.",
        12: "DaH vaj, please swear Daq jIH Sum joH'a', since jIH ghaj dealt kindly tlhej SoH, vetlh SoH je DichDaq Da kindly tlhej wIj vav tuq, je nob jIH a true token;",
        13: "je vetlh SoH DichDaq toD yIn wIj vav, wIj SoS, wIj loDnI'pu', je wIj sisters, je Hoch vetlh chaH ghaj, je DichDaq toD maj yIn vo' Hegh.”",
        14: "The loDpu' ja'ta' Daq Daj, “maj yIn vaD yours, chugh SoH yImev talk about vam business vo' ours; je 'oH DIchDaq taH, ghorgh joH'a' nob maH the puH, vetlh maH DichDaq Da kindly je truly tlhej SoH.”",
        15: "vaj ghaH chaw' chaH bIng Sum a cord vegh the window; vaD Daj tuq ghaHta' Daq the retlh vo' the reD, je ghaH yInta' Daq the reD.",
        16: "ghaH ja'ta' Daq chaH, “jaH Daq the HuD, lest the pursuers tu' SoH; je So' tlhIH'egh pa' wej jajmey, until the pursuers ghaj cheghta'. Afterward, SoH may jaH lIj way.”",
        17: "The loDpu' ja'ta' Daq Daj, “maH DichDaq taH guiltless vo' vam lIj oath nuq SoH ghaj chenmoHta' maH Daq swear.",
        18: "yIlegh, ghorgh maH ghoS Daq the puH, SoH DIchDaq bind vam tlhegh vo' Doq thread Daq the window nuq SoH ta'ta' chaw' maH bIng Sum. SoH DIchDaq tay'moH Daq SoH'egh Daq the tuq lIj vav, lIj SoS, lIj loDnI'pu', je Hoch lIj vav household.",
        19: "'oH DIchDaq taH vetlh 'Iv goes pa' vo' the doors vo' lIj tuq Daq the street, Daj 'Iw DichDaq taH Daq Daj nach, je maH DichDaq taH guiltless. 'Iv ghaH tlhej SoH Daq the tuq, Daj 'Iw DIchDaq taH Daq maj nach, chugh vay' ghop ghaH Daq ghaH.",
        20: "'ach chugh SoH talk about vam business vo' ours, vaj maH DIchDaq taH guiltless vo' lIj oath nuq SoH ghaj chenmoHta' maH Daq swear.”",
        21: "ghaH ja'ta', “According Daq lIj mu'mey, vaj taH 'oH.” ghaH ngeHta' chaH DoH, je chaH departed. ghaH tied the Doq tlhegh Daq the window.",
        22: "chaH mejta', je ghoSta' Daq the HuD, je stayed pa' wej jajmey, until the pursuers ghajta' cheghta'. The pursuers nejta' chaH throughout Hoch the way, 'ach ta'be' tu' chaH.",
        23: "vaj the cha' loDpu' cheghta', descended vo' the HuD, juSta' Dung, je ghoSta' Daq Joshua the puqloD vo' Nun; je chaH ja'ta' ghaH Hoch vetlh ghajta' qaSta' Daq chaH.",
        24: "chaH ja'ta' Daq Joshua, “Truly joH'a' ghajtaH toDta' Daq maj ghopmey Hoch the puH. Moreover, Hoch the nganpu' vo' the puH melt DoH qaSpa' maH.”",
    },
    3: {
        1: "Joshua rose Dung early Daq the po; je chaH vIHta' vo' Shittim, je ghoSta' Daq the Jordan, ghaH je Hoch the puqpu' vo' Israel. chaH yIntaH pa' qaSpa' chaH juSta' Dung.",
        2: "'oH qaSta' after wej jajmey, vetlh the officers mejta' vegh the midst vo' the raQ;",
        3: "je chaH ra'ta' the ghotpu, ja'ta', “ghorgh SoH legh the Duj vo' the lay' vo' joH'a' lIj joH'a', je the lalDan vumwI'pu' the Levites qeng 'oH, vaj SoH DIchDaq vIH vo' lIj Daq, je tlha' 'oH.",
        4: "Yet pa' DIchDaq taH a space joj SoH je 'oH, about cha' SaD cubits Sum juv. yImev ghoS Sum Daq 'oH, vetlh SoH may Sov the way Sum nuq SoH must jaH; vaD SoH ghaj ghobe' juSta' vam way qaSpa'.”",
        5: "Joshua ja'ta' Daq the ghotpu, “Sanctify tlhIH'egh; vaD wa'leS joH'a' DichDaq ta' wonders among SoH.”",
        6: "Joshua jatlhta' Daq the lalDan vumwI'pu', ja'ta', “tlhap Dung the Duj vo' the lay', je juS Dung qaSpa' the ghotpu.” chaH tlhapta' Dung the Duj vo' the lay', je mejta' qaSpa' the ghotpu.",
        7: "joH'a' ja'ta' Daq Joshua, “DaHjaj jIH DichDaq begin Daq magnify SoH Daq the leghpu' vo' Hoch Israel, vetlh chaH may Sov vetlh as jIH ghaHta' tlhej Moses, vaj jIH DichDaq taH tlhej SoH.",
        8: "SoH DIchDaq ra'ta'ghach mu'mey the lalDan vumwI'pu' 'Iv SIQ the Duj vo' the lay', ja'ta', ‘ghorgh SoH ghoS Daq the brink vo' the bIQmey vo' the Jordan, SoH DIchDaq Qam vIHHa' Daq the Jordan.'”",
        9: "Joshua ja'ta' Daq the puqpu' vo' Israel, “ghoS naDev, je Qoy the mu'mey vo' joH'a' lIj joH'a'.”",
        10: "Joshua ja'ta', “Hereby SoH DIchDaq Sov vetlh the yIntaH joH'a' ghaH among SoH, je vetlh ghaH DichDaq Hutlh fail drive the Canaanite, je the Hittite, je the Hivite, je the Perizzite, je the Girgashite, je the Amorite, je the Jebusite pa' vo' qaSpa' SoH.",
        11: "yIlegh, the Duj vo' the lay' vo' the joH vo' Hoch the tera' passes Dung qaSpa' SoH Daq the Jordan.",
        12: "DaH vaj tlhap cha' wa'maH loDpu' pa' vo' the tuqpu' vo' Israel, vaD Hoch tuq a loD.",
        13: "'oH DIchDaq ghoS Daq juS, ghorgh the soles vo' the qamDu' vo' the lalDan vumwI'pu' 'Iv SIQ the Duj vo' joH'a', the joH vo' Hoch the tera', leS Daq the bIQmey vo' the Jordan, vetlh the bIQmey vo' the Jordan DichDaq taH pe' litHa', 'ach the bIQmey vetlh ghoS bIng vo' Dung; je chaH DIchDaq Qam Daq wa' heap.”",
        14: "'oH qaSta', ghorgh the ghotpu vIHta' vo' chaj tents Daq juS Dung the Jordan, the lalDan vumwI'pu' 'Iv boghmoH the Duj vo' the lay' taH qaSpa' the ghotpu,",
        15: "je ghorgh chaH 'Iv boghmoH the Duj ghajta' ghoS Daq the Jordan, je the qamDu' vo' the lalDan vumwI'pu' 'Iv boghmoH the Duj ghajta' dipped Daq the edge vo' the bIQ (vaD the Jordan overflows Hoch its banks Hoch the poH vo' harvest),",
        16: "vetlh the bIQmey nuq ghoSta' bIng vo' Dung Qampu', je rose Dung Daq wa' heap, a Dun way litHa', Daq Adam, the veng vetlh ghaH retlh Zarethan; je chaH vetlh mejta' bIng toward the biQ'a' vo' the Arabah, 'ach the Salt biQ'a', were wholly pe' litHa'. vaj the ghotpu juSta' Dung nIH Daq Jericho.",
        17: "The lalDan vumwI'pu' 'Iv boghmoH the Duj vo' the lay' vo' joH'a' Qampu' firm Daq dry yav Daq the middle vo' the Jordan; je Hoch Israel juSta' Dung Daq dry yav, until Hoch the Hatlh ghajta' juSta' completely Dung the Jordan.",
    },
    4: {
        1: "'oH qaSta', ghorgh Hoch the Hatlh ghajta' completely juSta' Dung the Jordan, vetlh joH'a' jatlhta' Daq Joshua, ja'ta',",
        2: "“tlhap cha' wa'maH loDpu' pa' vo' the ghotpu, pa' vo' Hoch tuq a loD,",
        3: "je ra'ta'ghach mu'mey chaH, ja'ta', ‘tlhap vo' pa' vo' the middle vo' the Jordan, pa' vo' the Daq nuqDaq the priests' qamDu' Qampu' firm, cha' wa'maH naghmey, je carry chaH Dung tlhej SoH, je lay chaH bIng Daq the lodging Daq, nuqDaq SoH DichDaq juH tonight.'”",
        4: "vaj Joshua ja' the cha' wa'maH loDpu', 'Iv ghaH ghajta' prepared vo' the puqpu' vo' Israel, pa' vo' Hoch tuq a loD.",
        5: "Joshua ja'ta' Daq chaH, “juS Dung qaSpa' the Duj vo' joH'a' lIj joH'a' Daq the middle vo' the Jordan, je each vo' SoH pick Dung a nagh je lan 'oH Daq lIj shoulder, according Daq the mI' vo' the tuqpu' vo' the puqpu' vo' Israel;",
        6: "vetlh vam may taH a sign among SoH, vetlh ghorgh lIj puqpu' tlhob Daq poH Daq ghoS, ja'ta', ‘nuq ta' SoH mean Sum Dochvammey naghmey?'",
        7: "vaj SoH DIchDaq ja' chaH, ‘Because the bIQmey vo' the Jordan were pe' litHa' qaSpa' the Duj vo' the lay' vo' joH'a'. ghorgh 'oH juSta' Dung the Jordan, the bIQmey vo' the Jordan were pe' litHa'. Dochvammey naghmey DIchDaq taH vaD a memorial Daq the puqpu' vo' Israel reH.'”",
        8: "The puqpu' vo' Israel ta'ta' as Joshua ra'ta', je tlhapta' Dung cha' wa'maH naghmey pa' vo' the middle vo' the Jordan, as joH'a' jatlhta' Daq Joshua, according Daq the mI' vo' the tuqpu' vo' the puqpu' vo' Israel; je chaH qengta' chaH Dung tlhej chaH Daq the Daq nuqDaq chaH yIntaH, je laid chaH bIng pa'.",
        9: "Joshua cher Dung cha' wa'maH naghmey Daq the middle vo' the Jordan, Daq the Daq nuqDaq the qamDu' vo' the lalDan vumwI'pu' 'Iv boghmoH the Duj vo' the lay' Qampu'; je chaH 'oH pa' Daq vam jaj.",
        10: "vaD the lalDan vumwI'pu' 'Iv boghmoH the Duj Qampu' Daq the middle vo' the Jordan, until everything ghaHta' finished vetlh joH'a' ra'ta' Joshua Daq jatlh Daq the ghotpu, according Daq Hoch vetlh Moses ra'ta' Joshua; je the ghotpu hurried je juSta' Dung.",
        11: "'oH qaSta', ghorgh Hoch the ghotpu ghajta' completely juSta' Dung, vetlh the Duj vo' joH'a' juSta' Dung, tlhej the lalDan vumwI'pu', Daq the Daq vo' the ghotpu.",
        12: "The puqpu' vo' Reuben, je the puqpu' vo' Gad, je the bID- tuq vo' Manasseh, juSta' Dung armed qaSpa' the puqpu' vo' Israel, as Moses jatlhta' Daq chaH.",
        13: "About loSmaH SaD loDpu', ready je armed vaD veS juSta' Dung qaSpa' joH'a' Daq may', Daq the plains vo' Jericho.",
        14: "Daq vetlh jaj, joH'a' magnified Joshua Daq the leghpu' vo' Hoch Israel; je chaH feared ghaH, as chaH feared Moses, Hoch the jajmey vo' Daj yIn.",
        15: "joH'a' jatlhta' Daq Joshua, ja'ta',",
        16: "“ra'ta'ghach mu'mey the lalDan vumwI'pu' 'Iv SIQ the Duj vo' the testimony, vetlh chaH ghoS Dung pa' vo' the Jordan.”",
        17: "Joshua vaj ra'ta' the lalDan vumwI'pu', ja'ta', “ghoS Dung pa' vo' the Jordan!”",
        18: "'oH qaSta', ghorgh the lalDan vumwI'pu' 'Iv boghmoH the Duj vo' the lay' vo' joH'a' ghajta' ghoS Dung pa' vo' the middle vo' the Jordan, je the soles vo' the priests' qamDu' were qengta' Dung Daq the dry yav, vetlh the bIQmey vo' the Jordan cheghta' Daq chaj Daq, je mejta' Dung Hoch its banks, as qaSpa'.",
        19: "The ghotpu ghoSta' Dung pa' vo' the Jordan Daq the tenth jaj vo' the wa'Dich jar, je Dabta' Daq Gilgal, Daq the pemHov 'o' veH vo' Jericho.",
        20: "Joshua cher Dung chaH cha' wa'maH naghmey, nuq chaH tlhapta' pa' vo' the Jordan, Daq Gilgal.",
        21: "ghaH jatlhta' Daq the puqpu' vo' Israel, ja'ta', “ghorgh lIj puqpu' tlhob chaj vavpu' Daq poH Daq ghoS, ja'ta', ‘nuq ta' Dochvammey naghmey mean?'",
        22: "vaj SoH DIchDaq chaw' lIj puqpu' Sov, ja'ta', ‘Israel ghoSta' Dung vam Jordan Daq dry puH.",
        23: "vaD joH'a' lIj joH'a' dried Dung the bIQmey vo' the Jordan vo' qaSpa' SoH, until SoH ghajta' juSta' Dung, as joH'a' lIj joH'a' ta'ta' Daq the Doq biQ'a' { Note: joq, biQ'a' vo' Reeds }, nuq ghaH dried Dung vo' qaSpa' maH, until maH ghajta' juSta' Dung;",
        24: "vetlh Hoch the ghotpu' vo' the tera' may Sov the ghop vo' joH'a', vetlh 'oH ghaH HoS; vetlh SoH may taHvIp joH'a' lIj joH'a' reH.'”",
    },
    5: {
        1: "'oH qaSta', ghorgh Hoch the joHpu' vo' the Amorites, 'Iv were beyond the Jordan westward, je Hoch the joHpu' vo' the Canaanites, 'Iv were Sum the biQ'a', Qoyta' chay' vetlh joH'a' ghajta' dried Dung the bIQmey vo' the Jordan vo' qaSpa' the puqpu' vo' Israel, until maH ghajta' juSta' Dung, vetlh chaj tIq melted, ghobe' ghaHta' pa' qa' Daq chaH vay' latlh, because vo' the puqpu' vo' Israel.",
        2: "Daq vetlh poH, joH'a' ja'ta' Daq Joshua, “chenmoH flint knives, je circumcise again the puqpu' vo' Israel the cha'DIch poH.”",
        3: "Joshua chenmoHta' himself flint knives, je circumcised the puqpu' vo' Israel Daq the HuD vo' the foreskins.",
        4: "vam ghaH the meq Joshua circumcised: Hoch the ghotpu 'Iv ghoSta' pa' vo' Egypt, 'Iv were males, 'ach Hoch the loDpu' vo' veS, Heghta' Daq the ngem Sum the way, after chaH ghoSta' pa' vo' Egypt.",
        5: "vaD Hoch the ghotpu 'Iv ghoSta' pa' were circumcised; 'ach Hoch the ghotpu 'Iv were bogh Daq the ngem Sum the way as chaH ghoSta' pa' vo' Egypt ghajta' ghobe' taH circumcised.",
        6: "vaD the puqpu' vo' Israel yItta' loSmaH DISmey Daq the ngem, until Hoch the Hatlh, 'ach the loDpu' vo' veS 'Iv ghoSta' pa' vo' Egypt, were Soppu', because chaH ta'be' 'Ij Daq the ghogh vo' joH'a'. joH'a' swore Daq chaH vetlh ghaH wouldn't chaw' chaH legh the puH nuq joH'a' swore Daq chaj vavpu' vetlh ghaH would nob maH, a puH flowing tlhej milk je honey.",
        7: "chaj puqpu', 'Iv ghaH raised Dung Daq chaj Daq, were circumcised Sum Joshua; vaD chaH were uncircumcised, because chaH ghajta' ghobe' circumcised chaH Daq the way.",
        8: "'oH qaSta', ghorgh chaH were ta'pu' circumcising Hoch the Hatlh, vetlh chaH stayed Daq chaj Daqmey Daq the raQ until chaH were healed.",
        9: "joH'a' ja'ta' Daq Joshua, “DaHjaj jIH ghaj rolled DoH the reproach vo' Egypt vo' litHa' SoH.” vaj the pong vo' vetlh Daq ghaHta' ja' Gilgal, { Note: “Gilgal” wabmey rur the Hebrew vaD “roll.” } Daq vam jaj.",
        10: "The puqpu' vo' Israel Dabta' Daq Gilgal. chaH polta' the Passover Daq the fourteenth jaj vo' the jar Daq evening Daq the plains vo' Jericho.",
        11: "chaH ate unleavened cakes je parched grain vo' the produce vo' the puH Daq the next jaj after the Passover, Daq the rap jaj.",
        12: "The manna mevta' Daq the next jaj, after chaH ghajta' eaten vo' the produce vo' the puH. The puqpu' vo' Israel ta'be' ghaj manna vay' latlh; 'ach chaH ate vo' the baQ vo' the puH vo' Canaan vetlh DIS.",
        13: "'oH qaSta', ghorgh Joshua ghaHta' Sum Jericho, vetlh ghaH qengta' Dung Daj mInDu' je nejta', je yIlegh, a loD Qampu' Daq front vo' ghaH tlhej Daj 'etlh drawn Daq Daj ghop. Joshua mejta' Daq ghaH, je ja'ta' Daq ghaH, “'oH SoH vaD maH, joq vaD maj jaghpu'?”",
        14: "ghaH ja'ta', “ghobe'; 'ach jIH ghaj ghoS DaH as commander vo' joH'a' army.” Joshua pumta' Daq Daj qab Daq the tera', je worshipped, je ja'ta' Daq ghaH, “nuq ta'taH wIj joH jatlh Daq Daj toy'wI'?”",
        15: "The joHHom vo' joH'a' army ja'ta' Daq Joshua, “tlhap lIj shoes litHa' vo' lIj qamDu'; vaD the Daq Daq nuq SoH Qam ghaH le'.” Joshua ta'ta' vaj.",
    },
    6: {
        1: "DaH Jericho ghaHta' tightly shut Dung because vo' the puqpu' vo' Israel. ghobe' wa' mejta' pa', je ghobe' wa' ghoSta' Daq.",
        2: "joH'a' ja'ta' Daq Joshua, “yIlegh, jIH ghaj nobpu' Jericho Daq lIj ghop, tlhej its joH je the HoS loDpu' vo' valor.",
        3: "Hoch lIj loDpu' vo' veS DIchDaq march around the veng, ghoS around the veng once. SoH DIchDaq ta' vam jav jajmey.",
        4: "Soch lalDan vumwI'pu' DIchDaq SIQ Soch trumpets vo' rams' horns qaSpa' the Duj. Daq the SochDIch jaj, SoH DIchDaq march around the veng Soch poHmey, je the lalDan vumwI'pu' DIchDaq blow the trumpets.",
        5: "'oH DIchDaq taH vetlh ghorgh chaH chenmoH a tIq blast tlhej the ram's horn, je ghorgh SoH Qoy the wab vo' the trumpet, Hoch the ghotpu DIchDaq jach tlhej a Dun jach; je the reD vo' the veng DIchDaq pum bIng flat, je the ghotpu DIchDaq jaH Dung Hoch loD straight qaSpa' ghaH.”",
        6: "Joshua the puqloD vo' Nun ja' the lalDan vumwI'pu', je ja'ta' Daq chaH, “tlhap Dung the Duj vo' the lay', je chaw' Soch lalDan vumwI'pu' SIQ Soch trumpets vo' rams' horns qaSpa' the Duj vo' joH'a'.”",
        7: "chaH ja'ta' Daq the ghotpu, “Advance! March around the veng, je chaw' the armed loDpu' juS Daq qaSpa' joH'a' Duj.”",
        8: "'oH ghaHta' vaj, vetlh ghorgh Joshua ghajta' jatlhpu' Daq the ghotpu, the Soch lalDan vumwI'pu' qeng the Soch trumpets vo' rams' horns qaSpa' joH'a' advanced, je blew the trumpets; je the Duj vo' the lay' vo' joH'a' tlha'ta' chaH.",
        9: "The armed loDpu' mejta' qaSpa' the lalDan vumwI'pu' 'Iv blew the trumpets, je the Duj mejta' after chaH. The trumpets ghumta' as chaH mejta'.",
        10: "Joshua ra'ta' the ghotpu, ja'ta', “SoH DIchDaq ghobe' jach, ghobe' chaw' lIj ghogh taH Qoyta', ghobe' DIchDaq vay' mu' proceed pa' vo' lIj nujDu', until the jaj jIH ja' SoH Daq jach. vaj SoH DIchDaq jach.”",
        11: "vaj ghaH caused the Duj vo' joH'a' Daq jaH around the veng, ghoS about 'oH once. vaj chaH ghoSta' Daq the raQ, je yIntaH Daq the raQ.",
        12: "Joshua rose early Daq the po, je the lalDan vumwI'pu' tlhapta' Dung the Duj vo' joH'a'.",
        13: "The Soch lalDan vumwI'pu' qeng the Soch trumpets vo' rams' horns qaSpa' the Duj vo' joH'a' mejta' Daq continually, je blew the trumpets: je the armed loDpu' mejta' qaSpa' chaH. The rear guard ghoSta' after the Duj vo' joH'a'. The trumpets ghumta' as chaH mejta'.",
        14: "The cha'DIch jaj chaH marched around the veng once, je cheghta' Daq the raQ. chaH ta'ta' vam jav jajmey.",
        15: "'oH qaSta' Daq the SochDIch jaj, vetlh chaH rose early Daq the dawning vo' the jaj, je marched around the veng Daq the rap way Soch poHmey. neH Daq vam jaj chaH marched around the veng Soch poHmey.",
        16: "'oH qaSta' Daq the SochDIch poH, ghorgh the lalDan vumwI'pu' blew the trumpets, Joshua ja'ta' Daq the ghotpu, “jach, vaD joH'a' ghajtaH nobpu' SoH the veng!",
        17: "The veng DIchDaq taH devoted, 'ach 'oH je Hoch vetlh ghaH Daq 'oH, Daq joH'a'. neH Rahab the naybe'wI' DIchDaq yIn, ghaH je Hoch 'Iv 'oH tlhej Daj Daq the tuq, because ghaH hid the Duypu' vetlh maH ngeHta'.",
        18: "'ach as vaD SoH, neH pol tlhIH'egh vo' the devoted Doch, lest ghorgh SoH ghaj devoted 'oH, SoH tlhap vo' the devoted Doch; vaj would SoH chenmoH the raQ vo' Israel accursed, je Seng 'oH.",
        19: "'ach Hoch the baS chIS, je SuD baS, je Dujmey vo' brass je iron, 'oH le' Daq joH'a'. chaH DIchDaq ghoS Daq joH'a' treasury.”",
        20: "vaj the ghotpu jachta', je the lalDan vumwI'pu' blew the trumpets. 'oH qaSta', ghorgh the ghotpu Qoyta' the wab vo' the trumpet, vetlh the ghotpu jachta' tlhej a Dun jach, je the reD pumta' bIng flat, vaj vetlh the ghotpu mejta' Dung Daq the veng, Hoch loD straight qaSpa' ghaH, je chaH tlhapta' the veng.",
        21: "chaH utterly Qaw'ta' Hoch vetlh ghaHta' Daq the veng, both loD je be', both Qup je qan, je Qa', je Suy', je SarghHom, tlhej the edge vo' the 'etlh.",
        22: "Joshua ja'ta' Daq the cha' loDpu' 'Iv ghajta' spied pa' the puH, “jaH Daq the prostitute's tuq, je qem pa' vo' pa' the be' je Hoch vetlh ghaH ghajtaH, as SoH swore Daq Daj.”",
        23: "The Qup loDpu' 'Iv were spies mejta' Daq, je qempu' pa' Rahab tlhej Daj vav, Daj SoS, Daj loDnI'pu', je Hoch vetlh ghaH ghajta'. chaH je qempu' pa' Hoch Daj relatives, je chaH cher chaH outside vo' the raQ vo' Israel.",
        24: "chaH meQqu'pu' the veng tlhej qul, je Hoch vetlh ghaHta' Daq 'oH. neH chaH lan the baS chIS, the SuD baS, je the Dujmey vo' brass je vo' iron Daq the treasury vo' joH'a' tuq.",
        25: "'ach Rahab the naybe'wI', Daj vav household, je Hoch vetlh ghaH ghajta', Joshua toDpu' yIn. ghaH yInta' Daq the midst vo' Israel Daq vam jaj, because ghaH hid the Duypu', 'Iv Joshua ngeHta' Daq spy pa' Jericho.",
        26: "Joshua ra'ta' chaH tlhej an oath Daq vetlh poH, ja'ta', “Cursed ghaH the loD qaSpa' joH'a', 'Iv rises Dung je builds vam veng Jericho. tlhej the loss vo' Daj firstborn DIchDaq ghaH lay its foundation, je tlhej the loss vo' Daj youngest puqloD DIchDaq ghaH cher Dung its lojmItmey.”",
        27: "vaj joH'a' ghaHta' tlhej Joshua; je Daj fame ghaHta' Daq Hoch the puH.",
    },
    7: {
        1: "'ach the puqpu' vo' Israel committed a trespass Daq the devoted Dochmey; vaD Achan, the puqloD vo' Carmi, the puqloD vo' Zabdi, the puqloD vo' Zerah, vo' the tuq vo' Judah, tlhapta' 'op vo' the devoted Dochmey. vaj joH'a' QeH meQpu' Daq the puqpu' vo' Israel.",
        2: "Joshua ngeHta' loDpu' vo' Jericho Daq Ai, nuq ghaH retlh Beth Aven, Daq the pemHov 'o' retlh vo' Bethel, je jatlhta' Daq chaH, ja'ta', “jaH Dung je spy pa' the puH.” The loDpu' mejta' Dung je spied pa' Ai.",
        3: "chaH cheghta' Daq Joshua, je ja'ta' Daq ghaH, “yImev chaw' Hoch the ghotpu jaH Dung; 'ach chaw' about cha' joq wej SaD loDpu' jaH Dung je mup Ai. yImev chenmoH Hoch the ghotpu Daq toil pa', vaD pa' 'oH neH a few vo' chaH.”",
        4: "vaj about wej SaD loDpu' vo' the ghotpu mejta' Dung pa', je chaH Haw'ta' qaSpa' the loDpu' vo' Ai.",
        5: "The loDpu' vo' Ai struck about wejmaH- jav loDpu' vo' chaH, je chaH chased chaH vo' qaSpa' the lojmIt 'ach Daq Shebarim, je struck chaH Daq the descent. The tIQDu' vo' the ghotpu melted, je mojta' rur bIQ.",
        6: "Joshua tore Daj clothes, je pumta' Daq the tera' Daq Daj qab qaSpa' the Duj vo' joH'a' until the evening, ghaH je the quppu' vo' Israel; je chaH lan dust Daq chaj nachDu'.",
        7: "Joshua ja'ta', “Alas, joH joH'a', qatlh ghaj SoH qempu' vam ghotpu Dung the Jordan Daq Hoch, Daq toD maH Daq the ghop vo' the Amorites, Daq cause maH Daq chIlqu'? jIH wish vetlh maH ghajta' taH content je yInta' beyond the Jordan!",
        8: "Oh, joH, nuq DIchDaq jIH jatlh, after vetlh Israel ghajtaH tlhe'ta' chaj backs qaSpa' chaj jaghpu'!",
        9: "vaD the Canaanites je Hoch the nganpu' vo' the puH DichDaq Qoy vo' 'oH, je DichDaq surround maH, je pe' litHa' maj pong vo' the tera'. nuq DichDaq SoH ta' vaD lIj Dun pong?”",
        10: "joH'a' ja'ta' Daq Joshua, “tlhap Dung! qatlh 'oH SoH fallen Daq lIj qab rur vetlh?",
        11: "Israel ghajtaH yempu'. HIja', chaH ghaj 'ach transgressed wIj lay' nuq jIH ra'ta' chaH. HIja', chaH ghaj 'ach tlhappu' vo' the devoted Dochmey, je ghaj je stolen, je je deceived. chaH ghaj 'ach lan 'oH among chaj ghaj stuff.",
        12: "vaj the puqpu' vo' Israel ta'laHbe' Qam qaSpa' chaj jaghpu'. chaH tlhe' chaj backs qaSpa' chaj jaghpu', because chaH ghaj moj devoted vaD QIH. jIH DichDaq ghobe' taH tlhej SoH vay' latlh, unless SoH Qaw' the devoted Dochmey vo' among SoH.",
        13: "“tlhap Dung! Sanctify the ghotpu, je jatlh, ‘Sanctify tlhIH'egh vaD wa'leS, vaD joH'a', the joH'a' vo' Israel, jatlhtaH, “pa' ghaH a devoted Doch Daq the midst vo' SoH, Israel. SoH cannot Qam qaSpa' lIj jaghpu' until SoH tlhap DoH the devoted Doch vo' among SoH.”",
        14: "“‘Daq the po vaj SoH DIchDaq taH qempu' Sum Sum lIj tuqpu'. 'oH DIchDaq taH vetlh the tuq nuq joH'a' selects DIchDaq ghoS Sum Sum qorDu'pu'. The qorDu' nuq joH'a' selects DIchDaq ghoS Sum Sum households. The household nuq joH'a' selects DIchDaq ghoS Sum loD Sum loD.",
        15: "'oH DIchDaq taH, vetlh ghaH 'Iv ghaH tlhappu' tlhej the devoted Doch DIchDaq taH meQqu'pu' tlhej qul, ghaH je Hoch vetlh ghaH ghajtaH, because ghaH ghajtaH transgressed the lay' vo' joH'a', je because ghaH ghajtaH ta'pu' a disgraceful Doch Daq Israel.'”",
        16: "vaj Joshua rose Dung early Daq the po je qempu' Israel Sum Sum chaj tuqpu'. The tuq vo' Judah ghaHta' selected.",
        17: "ghaH qempu' Sum the qorDu' vo' Judah; je ghaH selected the qorDu' vo' the Zerahites. ghaH qempu' Sum the qorDu' vo' the Zerahites loD Sum loD, je Zabdi ghaHta' selected.",
        18: "ghaH qempu' Sum Daj household loD Sum loD, je Achan, the puqloD vo' Carmi, the puqloD vo' Zabdi, the puqloD vo' Zerah, vo' the tuq vo' Judah, ghaHta' selected.",
        19: "Joshua ja'ta' Daq Achan, “wIj puqloD, please nob batlh Daq joH'a', the joH'a' vo' Israel, je chenmoH confession Daq ghaH. ja' jIH DaH nuq SoH ghaj ta'pu'! yImev So' 'oH vo' jIH!”",
        20: "Achan jangta' Joshua, je ja'ta', “jIH ghaj truly yempu' Daq joH'a', the joH'a' vo' Israel, je vam ghaH nuq jIH ghaj ta'pu'.",
        21: "ghorgh jIH leghta' among the non a 'IH Babylonian robe, cha' vatlh shekels vo' baS chIS, je a wedge vo' SuD baS weighing vaghmaH shekels, vaj jIH coveted chaH je tlhapta' chaH. yIlegh, chaH 'oH hidden Daq the yav Daq the middle vo' wIj juHHom, tlhej the baS chIS bIng 'oH.”",
        22: "vaj Joshua ngeHta' Duypu', je chaH ran Daq the juHHom. yIlegh, 'oH ghaHta' hidden Daq Daj juHHom, tlhej the baS chIS bIng 'oH.",
        23: "chaH tlhapta' chaH vo' the middle vo' the juHHom, je qempu' chaH Daq Joshua je Daq Hoch the puqpu' vo' Israel. chaH laid chaH bIng qaSpa' joH'a'.",
        24: "Joshua, je Hoch Israel tlhej ghaH, tlhapta' Achan the puqloD vo' Zerah, the baS chIS, the robe, the wedge vo' SuD baS, Daj puqloDpu', Daj puqbe'pu', Daj cattle, Daj donkeys, Daj Suy', Daj juHHom, je Hoch vetlh ghaH ghajta'; je chaH qempu' chaH Dung Daq the ngech vo' Achor.",
        25: "Joshua ja'ta', “qatlh ghaj SoH troubled maH? joH'a' DichDaq Seng SoH vam jaj.” Hoch Israel stoned ghaH tlhej naghmey, je chaH meQpu' chaH tlhej qul je stoned chaH tlhej naghmey.",
        26: "chaH raised Dung ghaH a Dun heap vo' naghmey vetlh remains Daq vam jaj. joH'a' tlhe'ta' vo' the fierceness vo' Daj QeH. vaj the pong vo' vetlh Daq ghaHta' ja' “The ngech vo' Achor” Daq vam jaj.",
    },
    8: {
        1: "joH'a' ja'ta' Daq Joshua, “yImev taH vIp, ghobe' taH dismayed. tlhap Hoch the ghotpu vo' veS tlhej SoH, je Hu', jaH Dung Daq Ai. yIlegh, jIH ghaj nobpu' Daq lIj ghop the joH vo' Ai, tlhej Daj ghotpu, Daj veng, je Daj puH.",
        2: "SoH DIchDaq ta' Daq Ai je Daj joH as SoH ta'ta' Daq Jericho je Daj joH, except its non je its livestock, SoH DIchDaq tlhap vaD a plunder vaD tlhIH'egh. cher an ambush vaD the veng behind 'oH.”",
        3: "vaj Joshua Hu', je Hoch the ghotpu vo' veS, Daq jaH Dung Daq Ai. Joshua chose wejmaH SaD loDpu', the HoS loDpu' vo' valor, je ngeHta' chaH pa' Sum ram.",
        4: "ghaH ra'ta' chaH, ja'ta', “yIlegh, SoH DIchDaq Qot Daq ambush Daq the veng, behind the veng. yImev jaH very Hop vo' the veng, 'ach Hoch vo' SoH taH ready.",
        5: "jIH, je Hoch the ghotpu 'Iv 'oH tlhej jIH, DichDaq approach Daq the veng. 'oH DIchDaq qaS, ghorgh chaH ghoS pa' Daq maH, as Daq the wa'Dich, vetlh maH DichDaq Haw' qaSpa' chaH.",
        6: "chaH DichDaq ghoS pa' after maH, until maH ghaj drawn chaH DoH vo' the veng; vaD chaH DichDaq jatlh, ‘chaH Haw' qaSpa' maH, rur the wa'Dich poH.' vaj maH DichDaq Haw' qaSpa' chaH,",
        7: "je SoH DIchDaq Hu' Dung vo' the ambush, je tlhap possession vo' the veng; vaD joH'a' lIj joH'a' DichDaq toD 'oH Daq lIj ghop.",
        8: "'oH DIchDaq taH, ghorgh SoH ghaj seized Daq the veng, vetlh SoH DIchDaq cher the veng Daq qul. SoH DIchDaq ta' vam according Daq the mu' vo' joH'a'. yIlegh, jIH ghaj ra'ta' SoH.”",
        9: "Joshua ngeHta' chaH pa'; je chaH mejta' Daq cher Dung the ambush, je stayed joj Bethel je Ai, Daq the pemHov 'et retlh vo' Ai; 'ach Joshua stayed among the ghotpu vetlh ram.",
        10: "Joshua rose Dung early Daq the po, mustered the ghotpu, je mejta' Dung, ghaH je the quppu' vo' Israel, qaSpa' the ghotpu Daq Ai.",
        11: "Hoch the ghotpu, 'ach the loDpu' vo' veS 'Iv were tlhej ghaH, mejta' Dung, je drew Sum, je ghoSta' qaSpa' the veng, je Dabta' Daq the pemHov nIH retlh vo' Ai. DaH pa' ghaHta' a ngech joj ghaH je Ai.",
        12: "ghaH tlhapta' about vagh SaD loDpu', je cher chaH Daq ambush joj Bethel je Ai, Daq the pemHov 'et retlh vo' the veng.",
        13: "vaj chaH cher the ghotpu, 'ach Hoch the army 'Iv ghaHta' Daq the pemHov nIH vo' the veng, je chaj ambush Daq the pemHov 'et vo' the veng; je Joshua mejta' vetlh ram Daq the midst vo' the ngech.",
        14: "'oH qaSta', ghorgh the joH vo' Ai leghta' 'oH, vetlh chaH hurried je rose Dung early, je the loDpu' vo' the veng mejta' pa' Daq Israel Daq may', ghaH je Hoch Daj ghotpu, Daq the poH wIv, qaSpa' the Arabah; 'ach ghaH ta'be' Sov vetlh pa' ghaHta' an ambush Daq ghaH behind the veng.",
        15: "Joshua je Hoch Israel chenmoHta' as chugh chaH were beaten qaSpa' chaH, je Haw'ta' Sum the way vo' the ngem.",
        16: "Hoch the ghotpu 'Iv were Daq the veng were ja' tay' Daq pursue after chaH. chaH pursued Joshua, je were drawn DoH vo' the veng.",
        17: "pa' ghaHta' ghobe' a loD poS Daq Ai joq Beth El 'Iv ta'be' jaH pa' after Israel. chaH poS the veng poSmoH, je pursued Israel.",
        18: "joH'a' ja'ta' Daq Joshua, “Stretch pa' the javelin vetlh ghaH Daq lIj ghop toward Ai, vaD jIH DichDaq nob 'oH Daq lIj ghop.” Joshua stretched pa' the javelin vetlh ghaHta' Daq Daj ghop toward the veng.",
        19: "The ambush Hu' quickly pa' vo' chaj Daq, je chaH ran as soon as ghaH ghajta' stretched pa' Daj ghop, je 'elta' Daq the veng, je tlhapta' 'oH. chaH hurried je cher the veng Daq qul.",
        20: "ghorgh the loDpu' vo' Ai nejta' behind chaH, chaH leghta', je yIlegh, the tlhIch vo' the veng ascended Dung Daq chal, je chaH ghajta' ghobe' HoS Daq Haw' vam way joq vetlh way. The ghotpu 'Iv Haw'ta' Daq the ngem tlhe'ta' DoH Daq the pursuers.",
        21: "ghorgh Joshua je Hoch Israel leghta' vetlh the ambush ghajta' tlhappu' the veng, je vetlh the tlhIch vo' the veng ascended, vaj chaH tlhe'ta' again, je HoHta' the loDpu' vo' Ai.",
        22: "The others ghoSta' pa' vo' the veng Daq chaH, vaj chaH were Daq the midst vo' Israel, 'op Daq vam retlh, je 'op Daq vetlh retlh. chaH struck chaH, vaj vetlh chaH chaw' pagh vo' chaH remain joq escape.",
        23: "chaH captured the joH vo' Ai yIn, je qempu' ghaH Daq Joshua.",
        24: "'oH qaSta', ghorgh Israel ghajta' chenmoHta' an pItlh vo' killing Hoch the nganpu' vo' Ai Daq the yotlh, Daq the ngem Daq nuq chaH pursued chaH, je chaH ghajta' Hoch fallen Sum the edge vo' the 'etlh, until chaH were Soppu', vetlh Hoch Israel cheghta' Daq Ai, je struck 'oH tlhej the edge vo' the 'etlh.",
        25: "Hoch vetlh pumta' vetlh jaj, both vo' loDpu' je be'pu', were cha' wa'maH SaD, 'ach Hoch the loDpu' vo' Ai.",
        26: "vaD Joshua ta'be' draw DoH Daj ghop, tlhej nuq ghaH stretched pa' the javelin, until ghaH ghajta' utterly Qaw'ta' Hoch the nganpu' vo' Ai.",
        27: "neH the livestock je the non vo' vetlh veng Israel tlhapta' vaD prey Daq themselves, according Daq the mu' vo' joH'a' nuq ghaH ra'ta' Joshua.",
        28: "vaj Joshua meQqu'pu' Ai, je chenmoHta' 'oH a heap reH, 'ach a desolation, Daq vam jaj.",
        29: "ghaH hanged the joH vo' Ai Daq a Sor until the evening, je Daq the sundown Joshua ra'ta', je chaH tlhapta' Daj porgh bIng vo' the Sor, je threw 'oH Daq the entrance vo' the lojmIt vo' the veng, je raised a Dun heap vo' naghmey Daq 'oH vetlh remains Daq vam jaj.",
        30: "vaj Joshua chenta' an lalDanta' Daq Daq joH'a', the joH'a' vo' Israel, Daq Mount Ebal,",
        31: "as Moses the toy'wI' vo' joH'a' ra'ta' the puqpu' vo' Israel, as 'oH ghaH ghItlhta' Daq the paq vo' the chut vo' Moses, an lalDanta' Daq vo' uncut naghmey, Daq nuq ghobe' loD ghajta' qengta' Dung vay' iron. chaH nobta' meQqu'pu' nobmey Daq 'oH Daq joH'a', je sacrificed roj nobmey.",
        32: "ghaH wrote pa' Daq the naghmey a copy vo' the chut vo' Moses, nuq ghaH wrote Daq the Daq vo' the puqpu' vo' Israel.",
        33: "Hoch Israel, je chaj quppu' je officers, je chaj judges, Qampu' Daq vam retlh vo' the Duj je Daq vetlh retlh qaSpa' the lalDan vumwI'pu' the Levites, 'Iv qengta' the Duj vo' joH'a' lay', the foreigner as QaQ as the native; bID vo' chaH Daq front vo' Mount Gerizim, je bID vo' chaH Daq front vo' Mount Ebal, as Moses the toy'wI' vo' joH'a' ghajta' ra'ta' Daq the wa'Dich, vetlh chaH should ghurmoH the ghotpu vo' Israel.",
        34: "Afterward ghaH read Hoch the mu'mey vo' the chut, the blessing je the mu'qaD, according Daq Hoch vetlh ghaH ghItlhta' Daq the paq vo' the chut.",
        35: "pa' ghaHta' ghobe' a mu' vo' Hoch vetlh Moses ra'ta', nuq Joshua ta'be' read qaSpa' Hoch the yej vo' Israel, tlhej the be'pu', the mach ones, je the foreigners 'Iv were among chaH.",
    },
    9: {
        1: "'oH qaSta', ghorgh Hoch the joHpu' 'Iv were beyond the Jordan, Daq the HuD Hatlh, je Daq the lowland, je Daq Hoch the shore vo' the Dun biQ'a' Daq front vo' Lebanon, the Hittite, the Amorite, the Canaanite, the Perizzite, the Hivite, je the Jebusite, Qoyta' vo' 'oH",
        2: "vetlh chaH boSta' themselves tay' Daq Suv tlhej Joshua je tlhej Israel, tlhej wa' accord.",
        3: "'ach ghorgh the nganpu' vo' Gibeon Qoyta' nuq Joshua ghajta' ta'pu' Daq Jericho je Daq Ai,",
        4: "chaH je resorted Daq a ruse, je mejta' je chenmoHta' as chugh chaH ghajta' taH ambassadors, je tlhapta' qan sacks Daq chaj donkeys, je wineskins, qan je torn je bagh Dung,",
        5: "je qan je patched shoes Daq chaj qamDu', je wore qan garments. Hoch the tIr Soj vo' chaj provision ghaHta' dry je moldy.",
        6: "chaH mejta' Daq Joshua Daq the raQ Daq Gilgal, je ja'ta' Daq ghaH, je Daq the loDpu' vo' Israel, “maH ghaj ghoS vo' a Hop Hatlh. DaH vaj chenmoH a lay' tlhej maH.”",
        7: "The loDpu' vo' Israel ja'ta' Daq the Hivites, “nuq chugh SoH yIn among maH. chay' laH maH chenmoH a lay' tlhej SoH?”",
        8: "chaH ja'ta' Daq Joshua, “maH 'oH lIj toy'wI'pu'.” Joshua ja'ta' Daq chaH, “'Iv 'oH SoH? nuqDaq ta' SoH ghoS vo'?”",
        9: "chaH ja'ta' Daq ghaH, “lIj toy'wI'pu' ghaj ghoS vo' a very Hop Hatlh because vo' the pong vo' joH'a' lIj joH'a'; vaD maH ghaj Qoyta' vo' Daj fame, Hoch vetlh ghaH ta'ta' Daq Egypt,",
        10: "je Hoch vetlh ghaH ta'ta' Daq the cha' joHpu' vo' the Amorites 'Iv were beyond the Jordan, Daq Sihon joH vo' Heshbon je Daq Og joH vo' Bashan, 'Iv ghaHta' Daq Ashtaroth.",
        11: "maj quppu' je Hoch the nganpu' vo' maj Hatlh jatlhta' Daq maH, ja'ta', ‘tlhap provision Daq lIj ghop vaD the journey, je jaH Daq ghom chaH, je ja' chaH, “maH 'oH lIj toy'wI'pu'. DaH chenmoH a lay' tlhej maH.”'",
        12: "vam maj tIr Soj maH tlhapta' hot vaD maj provision pa' vo' maj juHmey Daq the jaj maH mejta' pa' Daq jaH Daq SoH; 'ach DaH, yIlegh, 'oH ghaH dry, je ghajtaH moj moldy.",
        13: "Dochvammey wineskins, nuq maH tebta', were chu'; je yIlegh, chaH 'oH torn. Dochvammey maj garments je maj shoes ghaj moj qan because vo' the very tIq journey.”",
        14: "The loDpu' sampled chaj provisions, je ta'be' tlhob qeS vo' the nujDu' vo' joH'a'.",
        15: "Joshua chenmoHta' roj tlhej chaH, je chenmoHta' a lay' tlhej chaH, Daq chaw' chaH yIn. The joHHom vo' the tay' ghotpu' swore Daq chaH.",
        16: "'oH qaSta' Daq the pItlh vo' wej jajmey after chaH ghajta' chenmoHta' a lay' tlhej chaH, vetlh chaH Qoyta' vetlh chaH were chaj neighbors, je vetlh chaH yInta' among chaH.",
        17: "The puqpu' vo' Israel traveled je ghoSta' Daq chaj vengmey Daq the wejDIch jaj. DaH chaj vengmey were Gibeon, Chephirah, Beeroth, je Kiriath Jearim.",
        18: "The puqpu' vo' Israel ta'be' mup chaH, because the joHHom vo' the tay' ghotpu' ghajta' sworn Daq chaH Sum joH'a', the joH'a' vo' Israel. Hoch the tay' ghotpu' murmured Daq the joHHom.",
        19: "'ach Hoch the joHHom ja'ta' Daq Hoch the tay' ghotpu', “maH ghaj sworn Daq chaH Sum joH'a', the joH'a' vo' Israel: DaH vaj maH may ghobe' touch chaH.",
        20: "vam maH DichDaq ta' Daq chaH, je chaw' chaH yIn; lest QeHpu' taH Daq maH, because vo' the oath nuq maH swore Daq chaH.”",
        21: "The joHHom ja'ta' Daq chaH, “chaw' chaH yIn, vaj chaH mojta' wood cutters je drawers vo' bIQ vaD Hoch the tay' ghotpu', as the joHHom ghajta' jatlhpu' Daq chaH.”",
        22: "Joshua ja' vaD chaH, je ghaH jatlhta' Daq chaH, ja'ta', “qatlh ghaj SoH deceived maH, ja'ta', ‘maH 'oH very Hop vo' SoH,' ghorgh SoH yIn among maH?",
        23: "DaH vaj SoH 'oH cursed, je 'op vo' SoH DichDaq never fail Daq taH bondservants, both wood cutters je drawers vo' bIQ vaD the tuq vo' wIj joH'a'.”",
        24: "chaH jangta' Joshua, je ja'ta', “Because lIj toy'wI'pu' were certainly ja'ta' chay' joH'a' lIj joH'a' ra'ta' Daj toy'wI' Moses Daq nob SoH Hoch the puH, je Daq Qaw' Hoch the nganpu' vo' the puH vo' qaSpa' SoH. vaj maH were very vIp vaD maj yIn because vo' SoH, je ghaj ta'pu' vam Doch.",
        25: "DaH, yIlegh, maH 'oH Daq lIj ghop. ta' Daq maH as 'oH seems QaQ je nIH Daq SoH Daq ta'.”",
        26: "ghaH ta'ta' vaj Daq chaH, je toDta' chaH pa' vo' the ghop vo' the puqpu' vo' Israel, vaj vetlh chaH ta'be' HoH chaH.",
        27: "vetlh jaj Joshua chenmoHta' chaH wood cutters je drawers vo' bIQ vaD the tay' ghotpu' je vaD the lalDanta' Daq vo' joH'a', Daq vam jaj, Daq the Daq nuq ghaH should choose.",
    },
    10: {
        1: "DaH 'oH qaSta' ghorgh Adoni-Zedek joH vo' Jerusalem Qoyta' chay' Joshua ghajta' tlhappu' Ai, je ghajta' utterly Qaw'ta' 'oH; as ghaH ghajta' ta'pu' Daq Jericho je Daj joH, vaj ghaH ghajta' ta'pu' Daq Ai je Daj joH; je chay' the nganpu' vo' Gibeon ghajta' chenmoHta' roj tlhej Israel, je were among chaH;",
        2: "vetlh chaH were very vIp, because Gibeon ghaHta' a Dun veng, as wa' vo' the royal vengmey, je because 'oH ghaHta' greater than Ai, je Hoch its loDpu' were HoS.",
        3: "vaj Adoni-Zedek joH vo' Jerusalem ngeHta' Daq Hoham joH vo' Hebron, Daq Piram joH vo' Jarmuth, Daq Japhia joH vo' Lachish, je Daq Debir joH vo' Eglon, ja'ta',",
        4: "“ghoS Dung Daq jIH, je QaH jIH, je chaw' maH mup Gibeon; vaD 'oH ghajtaH chenmoHta' roj tlhej Joshua je tlhej the puqpu' vo' Israel.”",
        5: "vaj the vagh joHpu' vo' the Amorites, the joH vo' Jerusalem, the joH vo' Hebron, the joH vo' Jarmuth, the joH vo' Lachish, the joH vo' Eglon, boSta' themselves tay', je mejta' Dung, chaH je Hoch chaj armies, je Dabta' Daq Gibeon, je chenmoHta' veS Daq 'oH.",
        6: "The loDpu' vo' Gibeon ngeHta' Daq Joshua Daq the raQ Daq Gilgal, ja'ta', “yImev abandon lIj toy'wI'pu'! ghoS Dung Daq maH quickly, je toD maH, je QaH maH; vaD Hoch the joHpu' vo' the Amorites vetlh yIn Daq the HuD Hatlh ghaj boSta' tay' Daq maH.”",
        7: "vaj Joshua mejta' Dung vo' Gilgal, ghaH, je Hoch the ghotpu vo' veS tlhej ghaH, je Hoch the HoS loDpu' vo' valor.",
        8: "joH'a' ja'ta' Daq Joshua, “yImev taHvIp chaH, vaD jIH ghaj toDta' chaH Daq lIj ghopmey. ghobe' a loD vo' chaH DichDaq Qam qaSpa' SoH.”",
        9: "Joshua vaj ghoSta' Daq chaH suddenly. ghaH mejta' Dung vo' Gilgal Hoch ram.",
        10: "joH'a' confused chaH qaSpa' Israel, je ghaH HoHta' chaH tlhej a Dun HoHqu' Daq Gibeon, je chased chaH Sum the way vo' the ascent vo' Beth Horon, je struck chaH Daq Azekah je Daq Makkedah.",
        11: "'oH qaSta', as chaH Haw'ta' vo' qaSpa' Israel, qaStaHvIS chaH were Daq the descent vo' Beth Horon, vetlh joH'a' chuH bIng Dun naghmey vo' the sky Daq chaH Daq Azekah, je chaH Heghta'. pa' were latlh 'Iv Heghta' vo' the hailstones than 'Iv the puqpu' vo' Israel HoHta' tlhej the 'etlh.",
        12: "vaj Joshua jatlhta' Daq joH'a' Daq the jaj ghorgh joH'a' toDta' Dung the Amorites qaSpa' the puqpu' vo' Israel; je ghaH ja'ta' Daq the leghpu' vo' Israel, “pemHov, Qam vIHHa' Daq Gibeon! SoH, maS, stop Daq the ngech vo' Aijalon!”",
        13: "The pemHov Qampu' vIHHa', je the maS stayed, until the Hatlh ghajta' avenged themselves vo' chaj jaghpu'. 'oHbe' vam ghItlhta' Daq the paq vo' Jashar? The pemHov stayed Daq the midst vo' the sky, je ta'be' hurry Daq jaH bIng about a Hoch jaj.",
        14: "pa' ghaHta' ghobe' jaj rur vetlh qaSpa' 'oH joq after 'oH, vetlh joH'a' listened Daq the ghogh vo' a loD; vaD joH'a' Suvta' vaD Israel.",
        15: "Joshua cheghta', je Hoch Israel tlhej ghaH, Daq the raQ Daq Gilgal.",
        16: "Dochvammey vagh joHpu' Haw'ta', je hid themselves Daq the cave Daq Makkedah.",
        17: "Joshua ghaHta' ja'ta', ja'ta', “The vagh joHpu' 'oH tu'ta', hidden Daq the cave Daq Makkedah.”",
        18: "Joshua ja'ta', “Roll large naghmey Daq the nujDu' vo' the cave, je cher loDpu' Sum 'oH Daq guard chaH;",
        19: "'ach yImev stay. Pursue lIj jaghpu', je chaH vo' the rear. yImev allow chaH Daq 'el Daq chaj vengmey; vaD joH'a' lIj joH'a' ghajtaH toDta' chaH Daq lIj ghop.”",
        20: "'oH qaSta', ghorgh Joshua je the puqpu' vo' Israel ghajta' finished killing chaH tlhej a very Dun HoHqu' until chaH were Soppu', je the chuv nuq remained vo' chaH ghajta' 'elta' Daq the fortified vengmey,",
        21: "vetlh Hoch the ghotpu cheghta' Daq the raQ Daq Joshua Daq Makkedah Daq roj. pagh vIHta' Daj jat Daq vay' vo' the puqpu' vo' Israel.",
        22: "vaj Joshua ja'ta', “poSmoH the nujDu' vo' the cave, je qem chaH vagh joHpu' pa' vo' the cave Daq jIH.”",
        23: "chaH ta'ta' vaj, je qempu' chaH vagh joHpu' pa' vo' the cave Daq ghaH: the joH vo' Jerusalem, the joH vo' Hebron, the joH vo' Jarmuth, the joH vo' Lachish, je the joH vo' Eglon.",
        24: "'oH qaSta', ghorgh chaH qempu' chaH joHpu' pa' Daq Joshua, vetlh Joshua ja' vaD Hoch the loDpu' vo' Israel, je ja'ta' Daq the chiefs vo' the loDpu' vo' veS 'Iv mejta' tlhej ghaH, “ghoS Sum, lan lIj qamDu' Daq the necks vo' Dochvammey joHpu'.” chaH ghoSta' Sum, je lan chaj qamDu' Daq chaj necks.",
        25: "Joshua ja'ta' Daq chaH, “yImev taH vIp, ghobe' taH dismayed. taH HoS je vo' QaQ courage, vaD joH'a' DichDaq ta' vam Daq Hoch lIj jaghpu' Daq 'Iv SoH Suv.”",
        26: 'Afterward Joshua struck chaH, lan chaH Daq Hegh, je hanged chaH Daq vagh Sormey. chaH were hanging Daq the Sormey until the evening.',
        27: "'oH qaSta' Daq the poH vo' the ghoS bIng vo' the pemHov, vetlh Joshua ra'ta', je chaH tlhapta' chaH bIng litHa' the Sormey, je chuH chaH Daq the cave Daq nuq chaH ghajta' hidden themselves, je laid Dun naghmey Daq the nujDu' vo' the cave, nuq remain Daq vam very jaj.",
        28: "Joshua tlhapta' Makkedah Daq vetlh jaj, je struck 'oH tlhej the edge vo' the 'etlh, tlhej its joH. ghaH utterly Qaw'ta' chaH je Hoch the qa'pu' 'Iv were Daq 'oH. ghaH poS pagh remaining. ghaH ta'ta' Daq the joH vo' Makkedah as ghaH ghajta' ta'pu' Daq the joH vo' Jericho.",
        29: "Joshua juSta' vo' Makkedah, je Hoch Israel tlhej ghaH, Daq Libnah, je Suvta' Daq Libnah.",
        30: "joH'a' toDta' 'oH je, tlhej its joH, Daq the ghop vo' Israel. ghaH struck 'oH tlhej the edge vo' the 'etlh, je Hoch the qa'pu' 'Iv were Daq 'oH. ghaH poS pagh remaining Daq 'oH. ghaH ta'ta' Daq its joH as ghaH ghajta' ta'pu' Daq the joH vo' Jericho.",
        31: "Joshua juSta' vo' Libnah, je Hoch Israel tlhej ghaH, Daq Lachish, je Dabta' Daq 'oH, je Suvta' Daq 'oH.",
        32: "joH'a' toDta' Lachish Daq the ghop vo' Israel. ghaH tlhapta' 'oH Daq the cha'DIch jaj, je struck 'oH tlhej the edge vo' the 'etlh, tlhej Hoch the qa'pu' 'Iv were Daq 'oH, according Daq Hoch vetlh ghaH ghajta' ta'pu' Daq Libnah.",
        33: "vaj Horam joH vo' Gezer ghoSta' Dung Daq QaH Lachish; je Joshua struck ghaH je Daj ghotpu, until ghaH ghajta' poS ghaH pagh remaining.",
        34: "Joshua juSta' vo' Lachish, je Hoch Israel tlhej ghaH, Daq Eglon; je chaH Dabta' Daq 'oH Suvta' Daq 'oH.",
        35: "chaH tlhapta' 'oH Daq vetlh jaj, je struck 'oH tlhej the edge vo' the 'etlh. ghaH utterly Qaw'ta' Hoch the qa'pu' 'Iv were Daq 'oH vetlh jaj, according Daq Hoch vetlh ghaH ghajta' ta'pu' Daq Lachish.",
        36: "Joshua mejta' Dung vo' Eglon, je Hoch Israel tlhej ghaH, Daq Hebron; je chaH Suvta' Daq 'oH.",
        37: "chaH tlhapta' 'oH, je struck 'oH tlhej the edge vo' the 'etlh, tlhej its joH je Hoch its vengmey, je Hoch the qa'pu' 'Iv were Daq 'oH. ghaH poS pagh remaining, according Daq Hoch vetlh ghaH ghajta' ta'pu' Daq Eglon; 'ach ghaH utterly Qaw'ta' 'oH, je Hoch the qa'pu' 'Iv were Daq 'oH.",
        38: "Joshua cheghta', je Hoch Israel tlhej ghaH, Daq Debir, je Suvta' Daq 'oH.",
        39: "ghaH tlhapta' 'oH, tlhej its joH je Hoch its vengmey. chaH struck chaH tlhej the edge vo' the 'etlh, je utterly Qaw'ta' Hoch the qa'pu' 'Iv were Daq 'oH. ghaH poS pagh remaining. As ghaH ghajta' ta'pu' Daq Hebron, vaj ghaH ta'ta' Daq Debir, je Daq its joH; as ghaH ghajta' ta'pu' je Daq Libnah, je Daq its joH.",
        40: "vaj Joshua struck Hoch the puH, the HuD Hatlh, je the pemHov poS, je the lowland, je the slopes, je Hoch chaj joHpu'. ghaH poS pagh remaining, 'ach ghaH utterly Qaw'ta' Hoch vetlh breathed, as joH'a', the joH'a' vo' Israel, ra'ta'.",
        41: "Joshua struck chaH vo' Kadesh Barnea 'ach Daq Gaza, je Hoch the Hatlh vo' Goshen, 'ach Daq Gibeon.",
        42: "Joshua tlhapta' Hoch Dochvammey joHpu' je chaj puH Daq wa' poH, because joH'a', the joH'a' vo' Israel, Suvta' vaD Israel.",
        43: "Joshua cheghta', je Hoch Israel tlhej ghaH, Daq the raQ Daq Gilgal.",
    },
    11: {
        1: "'oH qaSta', ghorgh Jabin joH vo' Hazor Qoyta' vo' 'oH, vetlh ghaH ngeHta' Daq Jobab joH vo' Madon, Daq the joH vo' Shimron, Daq the joH vo' Achshaph,",
        2: "je Daq the joHpu' 'Iv were Daq the pemHov nIH, Daq the HuD Hatlh, Daq the Arabah pemHov poS vo' Chinneroth, Daq the lowland, je Daq the heights vo' Dor Daq the pemHov 'et,",
        3: "Daq the Canaanite Daq the pemHov 'o' je Daq the pemHov 'et, je the Amorite, je the Hittite, je the Perizzite, je the Jebusite Daq the HuD Hatlh, je the Hivite bIng Hermon Daq the puH vo' Mizpah.",
        4: "chaH mejta' pa', chaH je Hoch chaj armies tlhej chaH, law' ghotpu, 'ach as the sand vetlh ghaH Daq the seashore Daq qevmey, tlhej very law' horses je Dujmey.",
        5: "Hoch Dochvammey joHpu' met tay'; je chaH ghoSta' je Dabta' tay' Daq the bIQmey vo' Merom, Daq Suv tlhej Israel.",
        6: "joH'a' ja'ta' Daq Joshua, “yImev taH vIp because vo' chaH; vaD wa'leS Daq vam poH, jIH DichDaq toD chaH Dung Hoch Heghta' qaSpa' Israel. SoH DIchDaq hamstring chaj horses je meQ chaj Dujmey tlhej qul.”",
        7: "vaj Joshua ghoSta', je Hoch the ghotpu vo' veS tlhej ghaH, Daq chaH Sum the bIQmey vo' Merom suddenly, je pumta' Daq chaH.",
        8: "joH'a' toDta' chaH Daq the ghop vo' Israel, je chaH struck chaH, je chased chaH Daq Dun Sidon, je Daq Misrephoth Maim, je Daq the ngech vo' Mizpeh eastward. chaH struck chaH until chaH poS chaH pagh remaining.",
        9: "Joshua ta'ta' Daq chaH as joH'a' ja'ta' ghaH. ghaH hamstrung chaj horses je meQqu'pu' chaj Dujmey tlhej qul.",
        10: "Joshua tlhe'ta' DoH Daq vetlh poH, je tlhapta' Hazor, je struck its joH tlhej the 'etlh: vaD Hazor used Daq taH the nach vo' Hoch chaH kingdoms.",
        11: "chaH struck Hoch the qa'pu' 'Iv were Daq 'oH tlhej the edge vo' the 'etlh, utterly destroying chaH. pa' ghaHta' ghobe' wa' poS 'Iv breathed. ghaH meQqu'pu' Hazor tlhej qul.",
        12: "Joshua captured Hoch the vengmey vo' chaH joHpu', tlhej chaj joHpu', je ghaH struck chaH tlhej the edge vo' the 'etlh, je utterly Qaw'ta' chaH; as Moses the toy'wI' vo' joH'a' ra'ta'.",
        13: "'ach as vaD the vengmey vetlh Qampu' Daq chaj mounds, Israel meQpu' pagh vo' chaH, except Hazor neH. Joshua meQpu' vetlh.",
        14: "The puqpu' vo' Israel tlhapta' Hoch the non vo' Dochvammey vengmey, tlhej the livestock, as spoils vaD themselves; 'ach Hoch loD chaH struck tlhej the edge vo' the 'etlh, until chaH ghajta' Qaw'ta' chaH. chaH ta'be' mej vay' 'Iv breathed.",
        15: "As joH'a' ra'ta' Moses Daj toy'wI', vaj Moses ra'ta' Joshua. Joshua ta'ta' vaj. ghaH poS pagh undone vo' Hoch vetlh joH'a' ra'ta' Moses.",
        16: "vaj Joshua captured Hoch vetlh puH, the HuD Hatlh, Hoch the pemHov poS, Hoch the puH vo' Goshen, the lowland, the Arabah, the HuD Hatlh vo' Israel, je the lowland vo' the rap;",
        17: "vo' Mount Halak, vetlh goes Dung Daq Seir, 'ach Daq Baal Gad Daq the ngech vo' Lebanon bIng Mount Hermon. ghaH tlhapta' Hoch chaj joHpu', struck chaH, je lan chaH Daq Hegh.",
        18: "Joshua chenmoHta' veS a tIq poH tlhej Hoch chaH joHpu'.",
        19: "pa' ghaHta' ghobe' a veng vetlh chenmoHta' roj tlhej the puqpu' vo' Israel, except the Hivites, the nganpu' vo' Gibeon. chaH tlhapta' Hoch Daq may'.",
        20: "vaD 'oH ghaHta' vo' joH'a' Daq harden chaj tIQDu', Daq ghoS Daq Israel Daq may', vetlh ghaH might utterly Qaw' chaH, vetlh chaH might ghaj ghobe' favor, 'ach vetlh ghaH might Qaw' chaH, as joH'a' ra'ta' Moses.",
        21: "Joshua ghoSta' Daq vetlh poH, je pe' litHa' the Anakim vo' the HuD Hatlh, vo' Hebron, vo' Debir, vo' Anab, je vo' Hoch the HuD Hatlh vo' Judah, je vo' Hoch the HuD Hatlh vo' Israel: Joshua utterly Qaw'ta' chaH tlhej chaj vengmey.",
        22: "pa' were pagh vo' the Anakim poS Daq the puH vo' the puqpu' vo' Israel. neH Daq Gaza, Daq Gath, je Daq Ashdod, ta'ta' 'op remain.",
        23: "vaj Joshua tlhapta' the Hoch puH, according Daq Hoch vetlh joH'a' jatlhta' Daq Moses; je Joshua nobta' 'oH vaD an inheritance Daq Israel according Daq chaj divisions Sum chaj tuqpu'. The puH ghajta' leS vo' veS.",
    },
    12: {
        1: "DaH Dochvammey 'oH the joHpu' vo' the puH, 'Iv the puqpu' vo' Israel struck, je possessed chaj puH beyond the Jordan toward the sunrise, vo' the ngech vo' the Arnon Daq Mount Hermon, je Hoch the Arabah eastward:",
        2: "Sihon joH vo' the Amorites, 'Iv yInta' Daq Heshbon, je ruled vo' Aroer, nuq ghaH Daq the edge vo' the ngech vo' the Arnon, je the middle vo' the ngech, je bID Gilead, 'ach Daq the bIQtIQ Jabbok, the veH vo' the puqpu' vo' Ammon;",
        3: "je the Arabah Daq the biQ'a' vo' Chinneroth, eastward, je Daq the biQ'a' vo' the Arabah, 'ach the Salt biQ'a', eastward, the way Daq Beth Jeshimoth; je Daq the pemHov poS, bIng the slopes vo' Pisgah:",
        4: "je the veH vo' Og joH vo' Bashan, vo' the chuv vo' the Rephaim, 'Iv yInta' Daq Ashtaroth je Daq Edrei,",
        5: "je ruled Daq Mount Hermon, je Daq Salecah, je Daq Hoch Bashan, Daq the veH vo' the Geshurites je the Maacathites, je bID Gilead, the veH vo' Sihon joH vo' Heshbon.",
        6: "Moses the toy'wI' vo' joH'a' je the puqpu' vo' Israel struck chaH. Moses the toy'wI' vo' joH'a' nobta' 'oH vaD a possession Daq the Reubenites, je the Gadites, je the bID- tuq vo' Manasseh.",
        7: "Dochvammey 'oH the joHpu' vo' the puH 'Iv Joshua je the puqpu' vo' Israel struck beyond the Jordan westward, vo' Baal Gad Daq the ngech vo' Lebanon 'ach Daq Mount Halak, vetlh goes Dung Daq Seir. Joshua nobta' 'oH Daq the tuqpu' vo' Israel vaD a possession according Daq chaj divisions;",
        8: 'Daq the HuD Hatlh, je Daq the lowland, je Daq the Arabah, je Daq the slopes, je Daq the ngem, je Daq the pemHov poS; the Hittite, the Amorite, je the Canaanite, the Perizzite, the Hivite, je the Jebusite:',
        9: "the joH vo' Jericho, wa'; the joH vo' Ai, nuq ghaH retlh Bethel, wa';",
        10: "the joH vo' Jerusalem, wa'; the joH vo' Hebron, wa';",
        11: "the joH vo' Jarmuth, wa'; the joH vo' Lachish, wa';",
        12: "the joH vo' Eglon, wa'; the joH vo' Gezer, wa';",
        13: "the joH vo' Debir, wa'; the joH vo' Geder, wa';",
        14: "the joH vo' Hormah, wa'; the joH vo' Arad, wa';",
        15: "the joH vo' Libnah, wa'; the joH vo' Adullam, wa';",
        16: "the joH vo' Makkedah, wa'; the joH vo' Bethel, wa';",
        17: "the joH vo' Tappuah, wa'; the joH vo' Hepher, wa';",
        18: "the joH vo' Aphek, wa'; the joH vo' Lassharon, wa';",
        19: "the joH vo' Madon, wa'; the joH vo' Hazor, wa';",
        20: "the joH vo' Shimron Meron, wa'; the joH vo' Achshaph, wa';",
        21: "the joH vo' Taanach, wa'; the joH vo' Megiddo, wa';",
        22: "the joH vo' Kedesh, wa'; the joH vo' Jokneam Daq Carmel, wa';",
        23: "the joH vo' Dor Daq the height vo' Dor, wa'; the joH vo' Goiim Daq Gilgal, wa';",
        24: "the joH vo' Tirzah, wa': Hoch the joHpu' wejmaH- wa'.",
    },
    13: {
        1: "DaH Joshua ghaHta' qan je QaQ advanced Daq DISmey. joH'a' ja'ta' Daq ghaH, “SoH 'oH qan je advanced Daq DISmey, je pa' remains yet very 'ar puH Daq taH possessed.",
        2: "“vam ghaH the puH vetlh vIHHa' remains: Hoch the regions vo' the Philistines, je Hoch the Geshurites;",
        3: "vo' the Shihor, nuq ghaH qaSpa' Egypt, 'ach Daq the veH vo' Ekron northward, nuq ghaH counted as Canaanite; the vagh lords vo' the Philistines; the Gazites, je the Ashdodites, the Ashkelonites, the Gittites, je the Ekronites; je the Avvim,",
        4: "Daq the pemHov poS; Hoch the puH vo' the Canaanites, je Mearah vetlh belongs Daq the Sidonians, Daq Aphek, Daq the veH vo' the Amorites;",
        5: "je the puH vo' the Gebalites, je Hoch Lebanon, toward the sunrise, vo' Baal Gad bIng Mount Hermon Daq the entrance vo' Hamath;",
        6: "Hoch the nganpu' vo' the HuD Hatlh vo' Lebanon Daq Misrephoth Maim, 'ach Hoch the Sidonians; chaH DichDaq jIH drive pa' vo' qaSpa' the puqpu' vo' Israel: neH allocate 'oH Daq Israel vaD an inheritance, as jIH ghaj ra'ta' SoH.",
        7: "DaH vaj divide vam puH vaD an inheritance Daq the Hut tuqpu' je the bID- tuq vo' Manasseh.”",
        8: "tlhej ghaH the Reubenites je the Gadites Hevta' chaj inheritance, nuq Moses nobta' chaH, beyond the Jordan eastward, 'ach as Moses the toy'wI' vo' joH'a' nobta' chaH:",
        9: "vo' Aroer, vetlh ghaH Daq the edge vo' the ngech vo' the Arnon, je the veng vetlh ghaH Daq the middle vo' the ngech, je Hoch the plain vo' Medeba Daq Dibon;",
        10: "je Hoch the vengmey vo' Sihon joH vo' the Amorites, 'Iv che'ta' Daq Heshbon, Daq the veH vo' the puqpu' vo' Ammon;",
        11: "je Gilead, je the veH vo' the Geshurites je Maacathites, je Hoch Mount Hermon, je Hoch Bashan Daq Salecah;",
        12: "Hoch the kingdom vo' Og Daq Bashan, 'Iv che'ta' Daq Ashtaroth je Daq Edrei (the rap ghaHta' poS vo' the chuv vo' the Rephaim); vaD Moses attacked Dochvammey, je drove chaH pa'.",
        13: "Nevertheless the puqpu' vo' Israel ta'be' drive pa' the Geshurites, ghobe' the Maacathites: 'ach Geshur je Maacath yIn Daq the midst vo' Israel Daq vam jaj.",
        14: "neH ghaH nobta' ghobe' inheritance Daq the tuq vo' Levi. The nobmey vo' joH'a', the joH'a' vo' Israel, chenmoHta' Sum qul 'oH Daj inheritance, as ghaH jatlhta' Daq ghaH.",
        15: "Moses nobta' Daq the tuq vo' the puqpu' vo' Reuben according Daq chaj qorDu'pu'.",
        16: "chaj veH ghaHta' vo' Aroer, vetlh ghaH Daq the edge vo' the ngech vo' the Arnon, je the veng vetlh ghaH Daq the middle vo' the ngech, je Hoch the plain Sum Medeba;",
        17: "Heshbon, je Hoch its vengmey vetlh 'oH Daq the plain; Dibon, Bamoth Baal, Beth Baal Meon,",
        18: 'Jahaz, Kedemoth, Mephaath,',
        19: "Kiriathaim, Sibmah, Zereth Shahar Daq the mount vo' the ngech,",
        20: "Beth Peor, the slopes vo' Pisgah, Beth Jeshimoth,",
        21: "Hoch the vengmey vo' the plain, je Hoch the kingdom vo' Sihon joH vo' the Amorites, 'Iv che'ta' Daq Heshbon, 'Iv Moses struck tlhej the chiefs vo' Midian, Evi, Rekem, Zur, Hur, je Reba, the joHHom vo' Sihon, 'Iv yInta' Daq the puH.",
        22: "The puqpu' vo' Israel alse HoHta' Balaam je the puqloD vo' Beor, the soothsayer, tlhej the 'etlh, among the leS vo' chaj Heghta'.",
        23: "The veH vo' the puqpu' vo' Reuben ghaHta' the bank vo' the Jordan. vam ghaHta' the inheritance vo' the puqpu' vo' Reuben according Daq chaj qorDu'pu', the vengmey je its villages.",
        24: "Moses nobta' Daq the tuq vo' Gad, Daq the puqpu' vo' Gad, according Daq chaj qorDu'pu'.",
        25: "chaj veH ghaHta' Jazer, je Hoch the vengmey vo' Gilead, je bID the puH vo' the puqpu' vo' Ammon, Daq Aroer vetlh ghaH qaSpa' Rabbah;",
        26: "je vo' Heshbon Daq Ramath Mizpeh, je Betonim; je vo' Mahanaim Daq the veH vo' Debir;",
        27: "je Daq the ngech, Beth Haram, Beth Nimrah, Succoth, je Zaphon, the leS vo' the kingdom vo' Sihon joH vo' Heshbon, the Jordan's bank, Daq the uttermost part vo' the biQ'a' vo' Chinnereth beyond the Jordan eastward.",
        28: "vam ghaH the inheritance vo' the puqpu' vo' Gad according Daq chaj qorDu'pu', the vengmey je its villages.",
        29: "Moses nobta' an inheritance Daq the bID- tuq vo' Manasseh. 'oH ghaHta' vaD the bID- tuq vo' the puqpu' vo' Manasseh according Daq chaj qorDu'pu'.",
        30: "chaj veH ghaHta' vo' Mahanaim, Hoch Bashan, Hoch the kingdom vo' Og joH vo' Bashan, je Hoch the towns vo' Jair, nuq 'oH Daq Bashan, javmaH vengmey.",
        31: "bID Gilead, Ashtaroth, je Edrei, the vengmey vo' the kingdom vo' Og Daq Bashan, were vaD the puqpu' vo' Machir the puqloD vo' Manasseh, 'ach vaD the bID vo' the puqpu' vo' Machir according Daq chaj qorDu'pu'.",
        32: "Dochvammey 'oH the inheritances nuq Moses distributed Daq the plains vo' Moab, beyond the Jordan Daq Jericho, eastward.",
        33: "'ach Daq the tuq vo' Levi Moses nobta' ghobe' inheritance. joH'a', the joH'a' vo' Israel, ghaH chaj inheritance, as ghaH jatlhta' Daq chaH.",
    },
    14: {
        1: "Dochvammey 'oH the inheritances nuq the puqpu' vo' Israel tlhapta' Daq the puH vo' Canaan, nuq Eleazar the lalDan vumwI', Joshua the puqloD vo' Nun, je the nachDu' vo' the fathers' juHmey vo' the tuqpu' vo' the puqpu' vo' Israel, distributed Daq chaH,",
        2: "Sum the lot vo' chaj inheritance, as joH'a' ra'ta' Sum Moses, vaD the Hut tuqpu', je vaD the bID- tuq.",
        3: "vaD Moses ghajta' nobpu' the inheritance vo' the cha' tuqpu' je the bID- tuq beyond the Jordan; 'ach Daq the Levites ghaH nobta' ghobe' inheritance among chaH.",
        4: "vaD the puqpu' vo' Joseph were cha' tuqpu', Manasseh je Ephraim: je chaH nobta' ghobe' portion Daq the Levites Daq the puH, except vengmey Daq yIn Daq, tlhej chaj suburbs vaD chaj livestock je vaD chaj property.",
        5: "The puqpu' vo' Israel ta'ta' as joH'a' ra'ta' Moses, je chaH divided the puH.",
        6: "vaj the puqpu' vo' Judah drew Sum Daq Joshua Daq Gilgal. Caleb the puqloD vo' Jephunneh the Kenizzite ja'ta' Daq ghaH, “SoH Sov the Doch vetlh joH'a' jatlhta' Daq Moses the loD vo' joH'a' concerning jIH je concerning SoH Daq Kadesh Barnea.",
        7: "jIH ghaHta' loSmaH DISmey qan ghorgh Moses the toy'wI' vo' joH'a' ngeHta' jIH vo' Kadesh Barnea Daq spy pa' the puH. jIH qempu' ghaH mu' again as 'oH ghaHta' Daq wIj tIq.",
        8: "Nevertheless, wIj loDnI'pu' 'Iv mejta' Dung tlhej jIH chenmoHta' the tIq vo' the ghotpu melt; 'ach jIH wholly tlha'ta' joH'a' wIj joH'a'.",
        9: "Moses swore Daq vetlh jaj, ja'ta', ‘DIch the puH nuqDaq SoH yItta' DIchDaq taH an inheritance Daq SoH je Daq lIj puqpu' reH, because SoH ghaj wholly tlha'ta' joH'a' wIj joH'a'.'",
        10: "“DaH, yIlegh, joH'a' ghajtaH polta' jIH yIn, as ghaH jatlhta', Dochvammey loSmaH- vagh DISmey, vo' the poH vetlh joH'a' jatlhta' vam mu' Daq Moses, qaStaHvIS Israel yItta' Daq the ngem. DaH, yIlegh, jIH 'oH eighty- vagh DISmey qan, DaHjaj.",
        11: "As yet jIH 'oH as HoS DaHjaj as jIH ghaHta' Daq the jaj vetlh Moses ngeHta' jIH: as wIj HoS ghaHta' vaj, 'ach vaj ghaH wIj HoS DaH vaD veS, Daq jaH pa' je Daq ghoS Daq.",
        12: "DaH vaj nob jIH vam HuD Hatlh, vo' nuq joH'a' jatlhta' Daq vetlh jaj; vaD SoH Qoyta' Daq vetlh jaj chay' the Anakim were pa', je Dun je fortified vengmey. 'oH may taH vetlh joH'a' DichDaq taH tlhej jIH, je jIH DIchDaq drive chaH pa', as joH'a' jatlhta'.”",
        13: "Joshua ghurtaH ghaH; je ghaH nobta' Hebron Daq Caleb the puqloD vo' Jephunneh vaD an inheritance.",
        14: "vaj Hebron mojta' the inheritance vo' Caleb the puqloD vo' Jephunneh the Kenizzite Daq vam jaj; because ghaH wholly tlha'ta' joH'a', the joH'a' vo' Israel.",
        15: "DaH the pong vo' Hebron qaSpa' ghaHta' Kiriath Arba, after the greatest loD among the Anakim. The puH ghajta' leS vo' veS.",
    },
    15: {
        1: "The lot vaD the tuq vo' the puqpu' vo' Judah according Daq chaj qorDu'pu' ghaHta' Daq the veH vo' Edom, 'ach Daq the ngem vo' Zin southward, Daq the uttermost part vo' the pemHov poS.",
        2: "chaj pemHov poS veH ghaHta' vo' the uttermost part vo' the Salt biQ'a', vo' the bay vetlh looks southward;",
        3: "je 'oH mejta' pa' southward vo' the ascent vo' Akrabbim, je juSta' along Daq Zin, je mejta' Dung Sum the pemHov poS vo' Kadesh Barnea, je juSta' along Sum Hezron, mejta' Dung Daq Addar, je tlhe'ta' about Daq Karka;",
        4: "je 'oH juSta' along Daq Azmon, mejta' pa' Daq the brook vo' Egypt; je the veH ended Daq the biQ'a'. vam DIchDaq taH lIj pemHov poS veH.",
        5: "The pemHov 'o' veH ghaHta' the Salt biQ'a', 'ach Daq the pItlh vo' the Jordan. The veH vo' the pemHov nIH quarter ghaHta' vo' the bay vo' the biQ'a' Daq the pItlh vo' the Jordan.",
        6: "The veH mejta' Dung Daq Beth Hoglah, je juSta' along Sum the pemHov nIH vo' Beth Arabah; je the veH mejta' Dung Daq the nagh vo' Bohan the puqloD vo' Reuben.",
        7: "The veH mejta' Dung Daq Debir vo' the ngech vo' Achor, je vaj northward, leghtaH toward Gilgal, vetlh ghaH Dung Daq the ascent vo' Adummim, nuq ghaH Daq the pemHov poS retlh vo' the bIQtIQ. The veH juSta' along Daq the bIQmey vo' En Shemesh, je ended Daq En Rogel.",
        8: "The veH mejta' Dung Sum the ngech vo' the puqloD vo' Hinnom Daq the retlh vo' the Jebusite southward (the rap ghaH Jerusalem); je the veH mejta' Dung Daq the top vo' the HuD vetlh lies qaSpa' the ngech vo' Hinnom westward, nuq ghaH Daq the farthest part vo' the ngech vo' Rephaim northward.",
        9: "The veH extended vo' the top vo' the HuD Daq the spring vo' the bIQmey vo' Nephtoah, je mejta' pa' Daq the vengmey vo' Mount Ephron; je the veH extended Daq Baalah (the rap ghaH Kiriath Jearim);",
        10: "je the veH tlhe'ta' about vo' Baalah westward Daq Mount Seir, je juSta' along Daq the retlh vo' Mount Jearim Daq the pemHov nIH (the rap ghaH Chesalon), je mejta' bIng Daq Beth Shemesh, je juSta' along Sum Timnah;",
        11: "je the veH mejta' pa' Daq the retlh vo' Ekron northward; je the veH extended Daq Shikkeron, je juSta' along Daq Mount Baalah, je mejta' pa' Daq Jabneel; je the goings pa' vo' the veH were Daq the biQ'a'.",
        12: "The pemHov 'et veH ghaHta' Daq the shore vo' the Dun biQ'a'. vam ghaH the veH vo' the puqpu' vo' Judah according Daq chaj qorDu'pu'.",
        13: "Daq Caleb the puqloD vo' Jephunneh ghaH nobta' a portion among the puqpu' vo' Judah, according Daq the ra'ta'ghach mu' vo' joH'a' Daq Joshua, 'ach Kiriath Arba, named after the vav vo' Anak (the rap ghaH Hebron).",
        14: "Caleb drove pa' the wej puqloDpu' vo' Anak: Sheshai, je Ahiman, je Talmai, the puqpu' vo' Anak.",
        15: "ghaH mejta' Dung Daq the nganpu' vo' Debir: DaH the pong vo' Debir qaSpa' ghaHta' Kiriath Sepher.",
        16: "Caleb ja'ta', “ghaH 'Iv strikes Kiriath Sepher, je takes 'oH, Daq ghaH DichDaq jIH nob Achsah wIj puqbe' as be'nal.”",
        17: "Othniel the puqloD vo' Kenaz, the loDnI' vo' Caleb, tlhapta' 'oH: je ghaH nobta' ghaH Achsah Daj puqbe' as be'nal.",
        18: "'oH qaSta', ghorgh ghaH ghoSta', vetlh ghaH ghajta' ghaH tlhob Daj vav fore a yotlh. ghaH got litHa' vo' Daj SarghHom, je Caleb ja'ta', “nuq ta' SoH want?”",
        19: "ghaH ja'ta', “nob jIH a blessing. Because SoH ghaj cher jIH Daq the puH vo' the pemHov poS, nob jIH je springs vo' bIQ.” ghaH nobta' Daj the upper springs je the lower springs.",
        20: "vam ghaH the inheritance vo' the tuq vo' the puqpu' vo' Judah according Daq chaj qorDu'pu'.",
        21: "The farthest vengmey vo' the tuq vo' the puqpu' vo' Judah toward the veH vo' Edom Daq the pemHov poS were Kabzeel, Eder, Jagur,",
        22: 'Kinah, Dimonah, Adadah,',
        23: 'Kedesh, Hazor, Ithnan,',
        24: 'Ziph, Telem, Bealoth,',
        25: 'Hazor Hadattah, Kerioth Hezron (the rap ghaH Hazor),',
        26: 'Amam, Shema, Moladah,',
        27: 'Hazar Gaddah, Heshmon, Beth Pelet,',
        28: 'Hazar Shual, Beersheba, Biziothiah,',
        29: 'Baalah, Iim, Ezem,',
        30: 'Eltolad, Chesil, Hormah,',
        31: 'Ziklag, Madmannah, Sansannah,',
        32: "Lebaoth, Shilhim, Ain, je Rimmon. Hoch the vengmey 'oH cha'maH- Hut, tlhej chaj villages.",
        33: 'Daq the lowland, Eshtaol, Zorah, Ashnah,',
        34: 'Zanoah, En Gannim, Tappuah, Enam,',
        35: 'Jarmuth, Adullam, Socoh, Azekah,',
        36: 'Shaaraim, Adithaim je Gederah (joq Gederothaim); fourteen vengmey tlhej chaj villages.',
        37: 'Zenan, Hadashah, Migdal Gad,',
        38: 'Dilean, Mizpeh, Joktheel,',
        39: 'Lachish, Bozkath, Eglon,',
        40: 'Cabbon, Lahmam, Chitlish,',
        41: "Gederoth, Beth Dagon, Naamah, je Makkedah; wa'maH jav vengmey tlhej chaj villages.",
        42: 'Libnah, Ether, Ashan,',
        43: 'Iphtah, Ashnah, Nezib,',
        44: 'Keilah, Achzib, je Mareshah; Hut vengmey tlhej chaj villages.',
        45: 'Ekron, tlhej its towns je its villages;',
        46: "vo' Ekron 'ach Daq the biQ'a', Hoch vetlh were Sum the retlh vo' Ashdod, tlhej chaj villages.",
        47: "Ashdod, its towns je its villages; Gaza, its towns je its villages; Daq the brook vo' Egypt, je the Dun biQ'a' tlhej its coastline.",
        48: 'Daq the HuD Hatlh, Shamir, Jattir, Socoh,',
        49: 'Dannah, Kiriath Sannah (nuq ghaH Debir),',
        50: 'Anab, Eshtemoh, Anim,',
        51: 'Goshen, Holon, je Giloh; eleven vengmey tlhej chaj villages.',
        52: 'Arab, Dumah, Eshan,',
        53: 'Janim, Beth Tappuah, Aphekah,',
        54: 'Humtah, Kiriath Arba (the rap ghaH Hebron), je Zior; Hut vengmey tlhej chaj villages.',
        55: 'Maon, Carmel, Ziph, Jutah,',
        56: 'Jezreel, Jokdeam, Zanoah,',
        57: "Kain, Gibeah, je Timnah; wa'maH vengmey tlhej chaj villages.",
        58: 'Halhul, Beth Zur, Gedor,',
        59: 'Maarath, Beth Anoth, je Eltekon; jav vengmey tlhej chaj villages.',
        60: "Kiriath Baal (the rap ghaH Kiriath Jearim), je Rabbah; cha' vengmey tlhej chaj villages.",
        61: 'Daq the ngem, Beth Arabah, Middin, Secacah,',
        62: "Nibshan, the veng vo' Salt, je En Gedi; jav vengmey tlhej chaj villages.",
        63: "As vaD the Jebusites, the nganpu' vo' Jerusalem, the puqpu' vo' Judah couldn't drive chaH pa'; 'ach the Jebusites yIn tlhej the puqpu' vo' Judah Daq Jerusalem Daq vam jaj.",
    },
    16: {
        1: "The lot ghoSta' pa' vaD the puqpu' vo' Joseph vo' the Jordan Daq Jericho, Daq the bIQmey vo' Jericho Daq the pemHov 'o', 'ach the ngem, ghoS Dung vo' Jericho vegh the HuD Hatlh Daq Bethel.",
        2: "'oH mejta' pa' vo' Bethel Daq Luz, je juSta' along Daq the veH vo' the Archites Daq Ataroth;",
        3: "je 'oH mejta' bIng westward Daq the veH vo' the Japhletites, Daq the veH vo' Beth Horon the lower, 'ach Daq Gezer; je ended Daq the biQ'a'.",
        4: "The puqpu' vo' Joseph, Manasseh je Ephraim, tlhapta' chaj inheritance.",
        5: "vam ghaHta' the veH vo' the puqpu' vo' Ephraim according Daq chaj qorDu'pu'. The veH vo' chaj inheritance eastward ghaHta' Ataroth Addar, Daq Beth Horon the upper.",
        6: "The veH mejta' pa' westward Daq Michmethath Daq the pemHov nIH. The veH tlhe'ta' about eastward Daq Taanath Shiloh, je juSta' along 'oH Daq the pemHov 'o' vo' Janoah.",
        7: "'oH mejta' bIng vo' Janoah Daq Ataroth, Daq Naarah, reached Daq Jericho, je mejta' pa' Daq the Jordan.",
        8: "vo' Tappuah the veH mejta' along westward Daq the brook vo' Kanah; je ended Daq the biQ'a'. vam ghaH the inheritance vo' the tuq vo' the puqpu' vo' Ephraim according Daq chaj qorDu'pu';",
        9: "tay' tlhej the vengmey nuq were cher apart vaD the puqpu' vo' Ephraim Daq the midst vo' the inheritance vo' the puqpu' vo' Manasseh, Hoch the vengmey tlhej chaj villages.",
        10: "chaH ta'be' drive pa' the Canaanites 'Iv yInta' Daq Gezer; 'ach the Canaanites yIn Daq the midst vo' Ephraim Daq vam jaj, je ghaj moj toy'wI'pu' Daq ta' forced labor.",
    },
    17: {
        1: "vam ghaHta' the lot vaD the tuq vo' Manasseh, vaD ghaH ghaHta' the firstborn vo' Joseph. As vaD Machir the firstborn vo' Manasseh, the vav vo' Gilead, because ghaH ghaHta' a loD vo' veS, vaj ghaH ghajta' Gilead je Bashan.",
        2: "vaj vam ghaHta' vaD the leS vo' the puqpu' vo' Manasseh according Daq chaj qorDu'pu': vaD the puqpu' vo' Abiezer, vaD the puqpu' vo' Helek, vaD the puqpu' vo' Asriel, vaD the puqpu' vo' Shechem, vaD the puqpu' vo' Hepher, je vaD the puqpu' vo' Shemida: Dochvammey were the male puqpu' vo' Manasseh the puqloD vo' Joseph according Daq chaj qorDu'pu'.",
        3: "'ach Zelophehad, the puqloD vo' Hepher, the puqloD vo' Gilead, the puqloD vo' Machir, the puqloD vo' Manasseh, ghajta' ghobe' puqloDpu', 'ach puqbe'pu': je Dochvammey 'oH the pongmey vo' Daj puqbe'pu': Mahlah, Noah, Hoglah, Milcah, je Tirzah.",
        4: "chaH ghoSta' Sum qaSpa' Eleazar the lalDan vumwI', je qaSpa' Joshua the puqloD vo' Nun, je qaSpa' the joHHom, ja'ta', “joH'a' ra'ta' Moses Daq nob maH an inheritance among maj loDnI'pu'.” vaj according Daq the ra'ta'ghach mu' vo' joH'a' ghaH nobta' chaH an inheritance among the loDnI'pu' vo' chaj vav.",
        5: "wa'maH parts pumta' Daq Manasseh, je the puH vo' Gilead je Bashan, nuq ghaH beyond the Jordan;",
        6: "because the puqbe'pu' vo' Manasseh ghajta' an inheritance among Daj puqloDpu'. The puH vo' Gilead belonged Daq the leS vo' the puqloDpu' vo' Manasseh.",
        7: "The veH vo' Manasseh ghaHta' vo' Asher Daq Michmethath, nuq ghaH qaSpa' Shechem. The veH mejta' along Daq the nIH ghop, Daq the nganpu' vo' En Tappuah.",
        8: "The puH vo' Tappuah belonged Daq Manasseh; 'ach Tappuah Daq the veH vo' Manasseh belonged Daq the puqpu' vo' Ephraim.",
        9: "The veH mejta' bIng Daq the brook vo' Kanah, southward vo' the brook. Dochvammey vengmey belonged Daq Ephraim among the vengmey vo' Manasseh. The veH vo' Manasseh ghaHta' Daq the pemHov nIH retlh vo' the brook, je ended Daq the biQ'a'.",
        10: "Southward 'oH ghaHta' Ephraim's, je northward 'oH ghaHta' Manasseh's, je the biQ'a' ghaHta' Daj veH. chaH reached Daq Asher Daq the pemHov nIH, je Daq Issachar Daq the pemHov 'o'.",
        11: "Manasseh ghajta' wej heights Daq Issachar, Daq Asher Beth Shean je its towns, je Ibleam je its towns, je the nganpu' vo' Dor je its towns, je the nganpu' vo' Endor je its towns, je the nganpu' vo' Taanach je its towns, je the nganpu' vo' Megiddo je its towns.",
        12: "Yet the puqpu' vo' Manasseh couldn't drive pa' the nganpu' vo' chaH vengmey; 'ach the Canaanites would yIn Daq vetlh puH.",
        13: "'oH qaSta', ghorgh the puqpu' vo' Israel ghajta' grown HoS, vetlh chaH lan the Canaanites Daq forced labor, je ta'be' utterly drive chaH pa'.",
        14: "The puqpu' vo' Joseph jatlhta' Daq Joshua, ja'ta', “qatlh ghaj SoH nobpu' jIH just wa' lot je wa' part vaD an inheritance, since jIH 'oH a Dun ghotpu, because joH'a' ghajtaH ghurtaH jIH vaj Hop?”",
        15: "Joshua ja'ta' Daq chaH, “chugh SoH 'oH a Dun ghotpu, jaH Dung Daq the forest, je clear puH vaD SoH'egh pa' Daq the puH vo' the Perizzites je vo' the Rephaim; since the HuD Hatlh vo' Ephraim ghaH too narrow vaD SoH.”",
        16: "The puqpu' vo' Joseph ja'ta', “The HuD Hatlh ghaH ghobe' yap vaD maH. Hoch the Canaanites 'Iv yIn Daq the puH vo' the ngech ghaj Dujmey vo' iron, both chaH 'Iv 'oH Daq Beth Shean je its towns, je chaH 'Iv 'oH Daq the ngech vo' Jezreel.”",
        17: "Joshua jatlhta' Daq the tuq vo' Joseph, 'ach Daq Ephraim je Daq Manasseh, ja'ta', “SoH 'oH a Dun ghotpu, je ghaj Dun HoS. SoH DIchDaq ghobe' ghaj wa' lot neH;",
        18: "'ach the HuD Hatlh DIchDaq taH yours. Although 'oH ghaH a forest, SoH DIchDaq pe' 'oH bIng, je it's farthest extent DIchDaq taH yours; vaD SoH DIchDaq drive pa' the Canaanites, 'a' chaH ghaj Dujmey vo' iron, je 'a' chaH 'oH HoS.”",
    },
    18: {
        1: "The Hoch tay' ghotpu' vo' the puqpu' vo' Israel assembled themselves tay' Daq Shiloh, je cher Dung the juHHom vo' qep pa'. The puH ghaHta' subdued qaSpa' chaH.",
        2: "Soch tuqpu' remained among the puqpu' vo' Israel, nuq ghajta' ghobe' yet divided chaj inheritance.",
        3: "Joshua ja'ta' Daq the puqpu' vo' Israel, “chay' tIq DichDaq SoH neglect Daq jaH Daq Daq ghaj the puH, nuq joH'a', the joH'a' vo' lIj vavpu', ghajtaH nobpu' SoH?",
        4: "Appoint vaD tlhIH'egh wej loDpu' vo' each tuq. jIH DichDaq ngeH chaH, je chaH DIchDaq Hu', yIt vegh the puH, je describe 'oH according Daq chaj inheritance; je chaH DIchDaq ghoS Daq jIH.",
        5: "chaH DIchDaq divide 'oH Daq Soch portions. Judah DIchDaq yIn Daq Daj veHmey Daq the pemHov poS, je the tuq vo' Joseph DIchDaq yIn Daq chaj veHmey Daq the pemHov nIH.",
        6: "SoH DIchDaq survey the puH Daq Soch parts, je qem the description naDev Daq jIH; je jIH DichDaq chuH lots vaD SoH naDev qaSpa' joH'a' maj joH'a'.",
        7: "vaD the Levites ghaj ghobe' portion among SoH; vaD the priesthood vo' joH'a' ghaH chaj inheritance. Gad, Reuben, je the bID- tuq vo' Manasseh ghaj Hevta' chaj inheritance beyond the Jordan eastward, nuq Moses the toy'wI' vo' joH'a' nobta' chaH.”",
        8: "The loDpu' Hu' je mejta'. Joshua ra'ta' chaH 'Iv mejta' Daq survey the puH, ja'ta', “jaH yIt vegh the puH, survey 'oH, je ghoS again Daq jIH. jIH DichDaq chuH lots vaD SoH naDev qaSpa' joH'a' Daq Shiloh.”",
        9: "The loDpu' mejta' je juSta' vegh the puH, je surveyed 'oH Sum vengmey Daq Soch portions Daq a paq. chaH ghoSta' Daq Joshua Daq the raQ Daq Shiloh.",
        10: "Joshua chuH lots vaD chaH Daq Shiloh qaSpa' joH'a'. pa' Joshua divided the puH Daq the puqpu' vo' Israel according Daq chaj divisions.",
        11: "The lot vo' the tuq vo' the puqpu' vo' Benjamin ghoSta' Dung according Daq chaj qorDu'pu'. The veH vo' chaj lot mejta' pa' joj the puqpu' vo' Judah je the puqpu' vo' Joseph.",
        12: "chaj veH Daq the pemHov nIH quarter ghaHta' vo' the Jordan. The veH mejta' Dung Daq the retlh vo' Jericho Daq the pemHov nIH, je mejta' Dung vegh the HuD Hatlh westward. 'oH ended Daq the ngem vo' Beth Aven.",
        13: "The veH juSta' along vo' pa' Daq Luz, Daq the retlh vo' Luz (the rap ghaH Bethel), southward. The veH mejta' bIng Daq Ataroth Addar, Sum the HuD vetlh lies Daq the pemHov poS vo' Beth Horon the lower.",
        14: "The veH extended, je tlhe'ta' around Daq the pemHov 'et quarter southward, vo' the HuD vetlh lies qaSpa' Beth Horon southward; je ended Daq Kiriath Baal (the rap ghaH Kiriath Jearim), a veng vo' the puqpu' vo' Judah. vam ghaHta' the pemHov 'et quarter.",
        15: "The pemHov poS quarter ghaHta' vo' the farthest part vo' Kiriath Jearim. The veH mejta' pa' westward, je mejta' pa' Daq the spring vo' the bIQmey vo' Nephtoah.",
        16: "The veH mejta' bIng Daq the farthest part vo' the HuD vetlh lies qaSpa' the ngech vo' the puqloD vo' Hinnom, nuq ghaH Daq the ngech vo' Rephaim northward. 'oH mejta' bIng Daq the ngech vo' Hinnom, Daq the retlh vo' the Jebusite southward, je mejta' bIng Daq En Rogel.",
        17: "'oH extended northward, mejta' pa' Daq En Shemesh, je mejta' pa' Daq Geliloth, nuq ghaH Dung Daq the ascent vo' Adummim. 'oH mejta' bIng Daq the nagh vo' Bohan the puqloD vo' Reuben.",
        18: "'oH juSta' along Daq the retlh Dung Daq the Arabah northward, je mejta' bIng Daq the Arabah.",
        19: "The veH juSta' along Daq the retlh vo' Beth Hoglah northward; je the veH ended Daq the pemHov nIH bay vo' the Salt biQ'a', Daq the pemHov poS pItlh vo' the Jordan. vam ghaHta' the pemHov poS veH.",
        20: "The Jordan ghaHta' its veH Daq the pemHov 'o' quarter. vam ghaHta' the inheritance vo' the puqpu' vo' Benjamin, Sum the veHmey around 'oH, according Daq chaj qorDu'pu'.",
        21: "DaH the vengmey vo' the tuq vo' the puqpu' vo' Benjamin according Daq chaj qorDu'pu' were Jericho, Beth Hoglah, Emek Keziz,",
        22: 'Beth Arabah, Zemaraim, Bethel,',
        23: 'Avvim, Parah, Ophrah,',
        24: "Chephar Ammoni, Ophni, je Geba; cha' wa'maH vengmey tlhej chaj villages.",
        25: 'Gibeon, Ramah, Beeroth,',
        26: 'Mizpeh, Chephirah, Mozah,',
        27: 'Rekem, Irpeel, Taralah,',
        28: "Zelah, Eleph, the Jebusite (the rap ghaH Jerusalem), Gibeath, je Kiriath; fourteen vengmey tlhej chaj villages. vam ghaH the inheritance vo' the puqpu' vo' Benjamin according Daq chaj qorDu'pu'.",
    },
    19: {
        1: "The cha'DIch lot ghoSta' pa' vaD Simeon, 'ach vaD the tuq vo' the puqpu' vo' Simeon according Daq chaj qorDu'pu'. chaj inheritance ghaHta' Daq the midst vo' the inheritance vo' the puqpu' vo' Judah.",
        2: "chaH ghajta' vaD chaj inheritance Beersheba (joq Sheba), Moladah,",
        3: 'Hazar Shual, Balah, Ezem,',
        4: 'Eltolad, Bethul, Hormah,',
        5: 'Ziklag, Beth Marcaboth, Hazar Susah,',
        6: 'Beth Lebaoth, je Sharuhen; thirteen vengmey tlhej chaj villages;',
        7: 'Ain, Rimmon, Ether, je Ashan; loS vengmey tlhej chaj villages;',
        8: "je Hoch the villages vetlh were around Dochvammey vengmey Daq Baalath Beer, Ramah vo' the pemHov poS. vam ghaH the inheritance vo' the tuq vo' the puqpu' vo' Simeon according Daq chaj qorDu'pu'.",
        9: "pa' vo' the part vo' the puqpu' vo' Judah ghaHta' the inheritance vo' the puqpu' vo' Simeon; vaD the portion vo' the puqpu' vo' Judah ghaHta' too 'ar vaD chaH. vaj the puqpu' vo' Simeon ghajta' inheritance Daq the midst vo' chaj inheritance.",
        10: "The wejDIch lot ghoSta' Dung vaD the puqpu' vo' Zebulun according Daq chaj qorDu'pu'. The veH vo' chaj inheritance ghaHta' Daq Sarid.",
        11: "chaj veH mejta' Dung westward, 'ach Daq Maralah, je reached Daq Dabbesheth. 'oH reached Daq the brook vetlh ghaH qaSpa' Jokneam.",
        12: "'oH tlhe'ta' vo' Sarid eastward toward the sunrise Daq the veH vo' Chisloth Tabor. 'oH mejta' pa' Daq Daberath, je mejta' Dung Daq Japhia.",
        13: "vo' pa' 'oH juSta' along eastward Daq Gath Hepher, Daq Ethkazin; je 'oH mejta' pa' Daq Rimmon nuq stretches Daq Neah.",
        14: "The veH tlhe'ta' around 'oH Daq the pemHov nIH Daq Hannathon; je 'oH ended Daq the ngech vo' Iphtah El;",
        15: "Kattath, Nahalal, Shimron, Idalah, je Bethlehem: cha' wa'maH vengmey tlhej chaj villages.",
        16: "vam ghaH the inheritance vo' the puqpu' vo' Zebulun according Daq chaj qorDu'pu', Dochvammey vengmey tlhej chaj villages.",
        17: "The fourth lot ghoSta' pa' vaD Issachar, 'ach vaD the puqpu' vo' Issachar according Daq chaj qorDu'pu'.",
        18: "chaj veH ghaHta' Daq Jezreel, Chesulloth, Shunem,",
        19: 'Hapharaim, Shion, Anaharath,',
        20: 'Rabbith, Kishion, Ebez,',
        21: 'Remeth, Engannim, En Haddah, je Beth Pazzez.',
        22: "The veH reached Daq Tabor, Shahazumah, je Beth Shemesh. chaj veH ended Daq the Jordan: wa'maH jav vengmey tlhej chaj villages.",
        23: "vam ghaH the inheritance vo' the tuq vo' the puqpu' vo' Issachar according Daq chaj qorDu'pu', the vengmey tlhej chaj villages.",
        24: "The fifth lot ghoSta' pa' vaD the tuq vo' the puqpu' vo' Asher according Daq chaj qorDu'pu'.",
        25: "chaj veH ghaHta' Helkath, Hali, Beten, Achshaph,",
        26: "Allammelech, Amad, Mishal. 'oH reached Daq Carmel westward, je Daq Shihorlibnath.",
        27: "'oH tlhe'ta' toward the sunrise Daq Beth Dagon, je reached Daq Zebulun, je Daq the ngech vo' Iphtah El northward Daq Beth Emek je Neiel. 'oH mejta' pa' Daq Cabul Daq the poS ghop,",
        28: "je Ebron, Rehob, Hammon, je Kanah, 'ach Daq Dun Sidon.",
        29: "The veH tlhe'ta' Daq Ramah, Daq the fortified veng vo' Tyre; je the veH tlhe'ta' Daq Hosah. 'oH ended Daq the biQ'a' Sum the region vo' Achzib;",
        30: "Ummah je, je Aphek, je Rehob: cha'maH- cha' vengmey tlhej chaj villages.",
        31: "vam ghaH the inheritance vo' the tuq vo' the puqpu' vo' Asher according Daq chaj qorDu'pu', Dochvammey vengmey tlhej chaj villages.",
        32: "The javDich lot ghoSta' pa' vaD the puqpu' vo' Naphtali, 'ach vaD the puqpu' vo' Naphtali according Daq chaj qorDu'pu'.",
        33: "chaj veH ghaHta' vo' Heleph, vo' the Sor'a' Daq Zaanannim, Adaminekeb, je Jabneel, Daq Lakkum. 'oH ended Daq the Jordan.",
        34: "The veH tlhe'ta' westward Daq Aznoth Tabor, je mejta' pa' vo' pa' Daq Hukkok. 'oH reached Daq Zebulun Daq the pemHov poS, je reached Daq Asher Daq the pemHov 'et, je Daq Judah Daq the Jordan toward the sunrise.",
        35: 'The fortified vengmey were Ziddim, Zer, Hammath, Rakkath, Chinnereth,',
        36: 'Adamah, Ramah, Hazor,',
        37: 'Kedesh, Edrei, En Hazor,',
        38: 'Iron, Migdal El, Horem, Beth Anath, je Beth Shemesh; nineteen vengmey tlhej chaj villages.',
        39: "vam ghaH the inheritance vo' the tuq vo' the puqpu' vo' Naphtali according Daq chaj qorDu'pu', the vengmey tlhej chaj villages.",
        40: "The SochDIch lot ghoSta' pa' vaD the tuq vo' the puqpu' vo' Dan according Daq chaj qorDu'pu'.",
        41: "The veH vo' chaj inheritance ghaHta' Zorah, Eshtaol, Irshemesh,",
        42: 'Shaalabbin, Aijalon, Ithlah,',
        43: 'Elon, Timnah, Ekron,',
        44: 'Eltekeh, Gibbethon, Baalath,',
        45: 'Jehud, Bene Berak, Gath Rimmon,',
        46: 'jIH Jarkon, je Rakkon, tlhej the veH Dung Daq Joppa.',
        47: "The veH vo' the puqpu' vo' Dan mejta' pa' beyond chaH; vaD the puqpu' vo' Dan mejta' Dung je Suvta' Daq Leshem, je tlhapta' 'oH, je struck 'oH tlhej the edge vo' the 'etlh, je possessed 'oH, je yInta' therein, je ja' Leshem, Dan, after the pong vo' Dan chaj vav.",
        48: "vam ghaH the inheritance vo' the tuq vo' the puqpu' vo' Dan according Daq chaj qorDu'pu', Dochvammey vengmey tlhej chaj villages.",
        49: "vaj chaH chenmoHta' an pItlh vo' distributing the puH vaD inheritance Sum its veHmey. The puqpu' vo' Israel nobta' an inheritance Daq Joshua the puqloD vo' Nun Daq the midst vo' chaH.",
        50: "According Daq the ra'ta'ghach mu' vo' joH'a', chaH nobta' ghaH the veng nuq ghaH tlhobta', 'ach Timnathserah Daq the HuD Hatlh vo' Ephraim; je ghaH chenta' the veng, je yInta' pa'.",
        51: "Dochvammey 'oH the inheritances, nuq Eleazar the lalDan vumwI', Joshua the puqloD vo' Nun, je the nachDu' vo' the fathers' juHmey vo' the tuqpu' vo' the puqpu' vo' Israel, distributed vaD inheritance Sum lot Daq Shiloh qaSpa' joH'a', Daq the lojmIt vo' the juHHom vo' qep. vaj chaH chenmoHta' an pItlh vo' dividing the puH.",
    },
    20: {
        1: "joH'a' jatlhta' Daq Joshua, ja'ta',",
        2: "“jatlh Daq the puqpu' vo' Israel, ja'ta', ‘Assign the vengmey vo' lulIgh, vo' nuq jIH jatlhta' Daq SoH Sum Moses,",
        3: "vetlh the manslayer 'Iv kills vay' person accidentally joq unintentionally may Haw' pa'. chaH DIchDaq taH Daq SoH vaD a lulIgh vo' the avenger vo' 'Iw.",
        4: "ghaH DIchDaq Haw' Daq wa' vo' chaH vengmey, je DIchDaq Qam Daq the entrance vo' the lojmIt vo' the veng, je declare Daj cause Daq the qoghDu' vo' the quppu' vo' vetlh veng. chaH DIchDaq tlhap ghaH Daq the veng tlhej chaH, je nob ghaH a Daq, vetlh ghaH may yIn among chaH.",
        5: "chugh the avenger vo' 'Iw pursue after ghaH, vaj chaH DIchDaq ghobe' toD Dung the manslayer Daq Daj ghop; because ghaH struck Daj jIl unintentionally, je ta'be' hate ghaH qaSpa'.",
        6: "ghaH DIchDaq yIn Daq vetlh veng until ghaH stands qaSpa' the tay' ghotpu' vaD yoj, until the Hegh vo' the jen lalDan vumwI' vetlh DIchDaq taH Daq chaH jajmey. vaj the manslayer DIchDaq chegh, je ghoS Daq Daj ghaj veng, je Daq Daj ghaj tuq, Daq the veng ghaH Haw'ta' vo'.'”",
        7: "chaH cher apart Kedesh Daq Galilee Daq the HuD Hatlh vo' Naphtali, Shechem Daq the HuD Hatlh vo' Ephraim, je Kiriath Arba (the rap ghaH Hebron) Daq the HuD Hatlh vo' Judah.",
        8: "Beyond the Jordan Daq Jericho eastward, chaH assigned Bezer Daq the ngem Daq the plain pa' vo' the tuq vo' Reuben, Ramoth Daq Gilead pa' vo' the tuq vo' Gad, je Golan Daq Bashan pa' vo' the tuq vo' Manasseh.",
        9: "Dochvammey were the wIv vengmey vaD Hoch the puqpu' vo' Israel, je vaD the stranger 'Iv sojourns among chaH, vetlh 'Iv kills vay' person unintentionally might Haw' pa', je ghobe' Hegh Sum the ghop vo' the avenger vo' 'Iw, until ghaH stands qaSpa' the tay' ghotpu'.",
    },
    21: {
        1: "vaj the nachDu' vo' fathers' juHmey vo' the Levites ghoSta' Sum Daq Eleazar the lalDan vumwI', je Daq Joshua the puqloD vo' Nun, je Daq the nachDu' vo' fathers' juHmey vo' the tuqpu' vo' the puqpu' vo' Israel.",
        2: "chaH jatlhta' Daq chaH Daq Shiloh Daq the puH vo' Canaan, ja'ta', “joH'a' ra'ta' Moses Daq nob maH vengmey Daq yIn Daq, tlhej chaj suburbs vaD maj livestock.”",
        3: "The puqpu' vo' Israel nobta' Daq the Levites pa' vo' chaj inheritance, according Daq the ra'ta'ghach mu' vo' joH'a', Dochvammey vengmey tlhej chaj suburbs.",
        4: "The lot ghoSta' pa' vaD the qorDu'pu' vo' the Kohathites. The puqpu' vo' Aaron the lalDan vumwI', 'Iv were vo' the Levites, ghajta' thirteen vengmey Sum lot pa' vo' the tuq vo' Judah, pa' vo' the tuq vo' the Simeonites, je pa' vo' the tuq vo' Benjamin.",
        5: "The leS vo' the puqpu' vo' Kohath ghajta' wa'maH vengmey Sum lot pa' vo' the qorDu'pu' vo' the tuq vo' Ephraim, pa' vo' the tuq vo' Dan, je pa' vo' the bID- tuq vo' Manasseh.",
        6: "The puqpu' vo' Gershon ghajta' thirteen vengmey Sum lot pa' vo' the qorDu'pu' vo' the tuq vo' Issachar, pa' vo' the tuq vo' Asher, pa' vo' the tuq vo' Naphtali, je pa' vo' the bID- tuq vo' Manasseh Daq Bashan.",
        7: "The puqpu' vo' Merari according Daq chaj qorDu'pu' ghajta' cha' wa'maH vengmey pa' vo' the tuq vo' Reuben, pa' vo' the tuq vo' Gad, je pa' vo' the tuq vo' Zebulun.",
        8: "The puqpu' vo' Israel nobta' Dochvammey vengmey tlhej chaj suburbs Sum lot Daq the Levites, as joH'a' ra'ta' Sum Moses.",
        9: "chaH nobta' pa' vo' the tuq vo' the puqpu' vo' Judah, je pa' vo' the tuq vo' the puqpu' vo' Simeon, Dochvammey vengmey nuq 'oH mentioned Sum pong:",
        10: "je chaH were vaD the puqpu' vo' Aaron, vo' the qorDu'pu' vo' the Kohathites, 'Iv were vo' the puqpu' vo' Levi; vaD theirs ghaHta' the wa'Dich lot.",
        11: "chaH nobta' chaH Kiriath Arba, named after the vav vo' Anak (the rap ghaH Hebron), Daq the HuD Hatlh vo' Judah, tlhej its suburbs around 'oH.",
        12: "'ach chaH nobta' the fields vo' the veng je its villages Daq Caleb the puqloD vo' Jephunneh vaD Daj possession.",
        13: "Daq the puqpu' vo' Aaron the lalDan vumwI' chaH nobta' Hebron tlhej its suburbs, the veng vo' lulIgh vaD the manslayer, Libnah tlhej its suburbs,",
        14: 'Jattir tlhej its suburbs, Eshtemoa tlhej its suburbs,',
        15: 'Holon tlhej its suburbs, Debir tlhej its suburbs,',
        16: "Ain tlhej its suburbs, Juttah tlhej its suburbs, je Beth Shemesh tlhej its suburbs; Hut vengmey pa' vo' chaH cha' tuqpu'.",
        17: "pa' vo' the tuq vo' Benjamin, Gibeon tlhej its suburbs, Geba tlhej its suburbs,",
        18: 'Anathoth tlhej its suburbs, je Almon tlhej its suburbs; loS vengmey.',
        19: "Hoch the vengmey vo' the puqpu' vo' Aaron, the lalDan vumwI'pu', were thirteen vengmey tlhej chaj suburbs.",
        20: "The qorDu'pu' vo' the puqpu' vo' Kohath, the Levites, 'ach the leS vo' the puqpu' vo' Kohath, ghajta' the vengmey vo' chaj lot pa' vo' the tuq vo' Ephraim.",
        21: "chaH nobta' chaH Shechem tlhej its suburbs Daq the HuD Hatlh vo' Ephraim, the veng vo' lulIgh vaD the manslayer, je Gezer tlhej its suburbs,",
        22: 'Kibzaim tlhej its suburbs, je Beth Horon tlhej its suburbs; loS vengmey.',
        23: "pa' vo' the tuq vo' Dan, Elteke tlhej its suburbs, Gibbethon tlhej its suburbs,",
        24: 'Aijalon tlhej its suburbs, Gath Rimmon tlhej its suburbs; loS vengmey.',
        25: "pa' vo' the bID- tuq vo' Manasseh, Taanach tlhej its suburbs, je Gath Rimmon tlhej its suburbs; cha' vengmey.",
        26: "Hoch the vengmey vo' the qorDu'pu' vo' the leS vo' the puqpu' vo' Kohath were wa'maH tlhej chaj suburbs.",
        27: "chaH nobta' Daq the puqpu' vo' Gershon, vo' the qorDu'pu' vo' the Levites, pa' vo' the bID- tuq vo' Manasseh Golan Daq Bashan tlhej its suburbs, the veng vo' lulIgh vaD the manslayer, je taH Eshterah tlhej its suburbs; cha' vengmey.",
        28: "pa' vo' the tuq vo' Issachar, Kishion tlhej its suburbs, Daberath tlhej its suburbs,",
        29: 'Jarmuth tlhej its suburbs, En Gannim tlhej its suburbs; loS vengmey.',
        30: "pa' vo' the tuq vo' Asher, Mishal tlhej its suburbs, Abdon tlhej its suburbs,",
        31: 'Helkath tlhej its suburbs, je Rehob tlhej its suburbs; loS vengmey.',
        32: "pa' vo' the tuq vo' Naphtali, Kedesh Daq Galilee tlhej its suburbs, the veng vo' lulIgh vaD the manslayer, Hammothdor tlhej its suburbs, je Kartan tlhej its suburbs; wej vengmey.",
        33: "Hoch the vengmey vo' the Gershonites according Daq chaj qorDu'pu' were thirteen vengmey tlhej chaj suburbs.",
        34: "Daq the qorDu'pu' vo' the puqpu' vo' Merari, the leS vo' the Levites, pa' vo' the tuq vo' Zebulun, Jokneam tlhej its suburbs, Kartah tlhej its suburbs,",
        35: 'Dimnah tlhej its suburbs, je Nahalal tlhej its suburbs; loS vengmey.',
        36: "pa' vo' the tuq vo' Reuben, Bezer tlhej its suburbs, Jahaz tlhej its suburbs,",
        37: 'Kedemoth tlhej its suburbs, je Mephaath tlhej its suburbs; loS vengmey.',
        38: "pa' vo' the tuq vo' Gad, Ramoth Daq Gilead tlhej its suburbs, the veng vo' lulIgh vaD the manslayer, je Mahanaim tlhej its suburbs,",
        39: 'Heshbon tlhej its suburbs, Jazer tlhej its suburbs; loS vengmey Daq Hoch.',
        40: "Hoch Dochvammey were the vengmey vo' the puqpu' vo' Merari according Daq chaj qorDu'pu', 'ach the leS vo' the qorDu'pu' vo' the Levites. chaj lot ghaHta' cha' wa'maH vengmey.",
        41: "Hoch the vengmey vo' the Levites Daq the midst vo' the possession vo' the puqpu' vo' Israel were loSmaH-eight vengmey tlhej chaj suburbs.",
        42: "Each vo' Dochvammey vengmey included chaj suburbs around chaH. 'oH ghaHta' vam way tlhej Hoch Dochvammey vengmey.",
        43: "vaj joH'a' nobta' Daq Israel Hoch the puH nuq ghaH swore Daq nob Daq chaj vavpu'. chaH possessed 'oH, je yInta' Daq 'oH.",
        44: "joH'a' nobta' chaH leS Hoch around, according Daq Hoch vetlh ghaH swore Daq chaj vavpu'. ghobe' a loD vo' Hoch chaj jaghpu' Qampu' qaSpa' chaH. joH'a' toDta' Hoch chaj jaghpu' Daq chaj ghop.",
        45: "pagh failed vo' vay' QaQ Doch nuq joH'a' ghajta' jatlhpu' Daq the tuq vo' Israel. Hoch ghoSta' Daq juS.",
    },
    22: {
        1: "vaj Joshua ja' the Reubenites, the Gadites, je the bID- tuq vo' Manasseh,",
        2: "je ja'ta' Daq chaH, “SoH ghaj polta' Hoch vetlh Moses the toy'wI' vo' joH'a' ra'ta' SoH, je ghaj listened Daq wIj ghogh Daq Hoch vetlh jIH ra'ta' SoH.",
        3: "SoH ghaj ghobe' poS lIj loDnI'pu' Dochvammey law' jajmey Daq vam jaj, 'ach ghaj performed the duty vo' the ra'ta'ghach mu' vo' joH'a' lIj joH'a'.",
        4: "DaH joH'a' lIj joH'a' ghajtaH nobpu' leS Daq lIj loDnI'pu', as ghaH jatlhta' Daq chaH. vaj DaH chegh je jaH Daq lIj tents, Daq the puH vo' lIj possession, nuq Moses the toy'wI' vo' joH'a' nobta' SoH beyond the Jordan.",
        5: "neH tlhap diligent heed Daq ta' the ra'ta'ghach mu' je the chut nuq Moses the toy'wI' vo' joH'a' ra'ta' SoH, Daq muSHa' joH'a' lIj joH'a', Daq yIt Daq Hoch Daj Hemey, Daq pol Daj ra'ta'ghach mu'mey, Daq 'uch fast Daq ghaH, je Daq toy' ghaH tlhej Hoch lIj tIq je tlhej Hoch lIj qa'.”",
        6: "vaj Joshua ghurtaH chaH, je ngeHta' chaH DoH; je chaH mejta' Daq chaj tents.",
        7: "DaH Daq the wa' bID- tuq vo' Manasseh Moses ghajta' nobpu' inheritance Daq Bashan; 'ach Daq the latlh bID nobta' Joshua among chaj loDnI'pu' beyond the Jordan westward. Moreover ghorgh Joshua ngeHta' chaH DoH Daq chaj tents, ghaH ghurtaH chaH,",
        8: "je jatlhta' Daq chaH, ja'ta', “chegh tlhej 'ar wealth Daq lIj tents, tlhej very 'ar livestock, tlhej baS chIS, tlhej SuD baS, tlhej brass, tlhej iron, je tlhej very 'ar Sut. Divide the non vo' lIj jaghpu' tlhej lIj loDnI'pu'.”",
        9: "The puqpu' vo' Reuben je the puqpu' vo' Gad je the bID- tuq vo' Manasseh cheghta', je departed vo' the puqpu' vo' Israel pa' vo' Shiloh, nuq ghaH Daq the puH vo' Canaan, Daq jaH Daq the puH vo' Gilead, Daq the puH vo' chaj possession, nuq chaH owned, according Daq the ra'ta'ghach mu' vo' joH'a' Sum Moses.",
        10: "ghorgh chaH ghoSta' Daq the region about the Jordan, vetlh ghaH Daq the puH vo' Canaan, the puqpu' vo' Reuben je the puqpu' vo' Gad je the bID- tuq vo' Manasseh chenta' pa' an lalDanta' Daq Sum the Jordan, a Dun lalDanta' Daq Daq legh Daq.",
        11: "The puqpu' vo' Israel Qoyta' vam, “yIlegh, the puqpu' vo' Reuben je the puqpu' vo' Gad je the bID- tuq vo' Manasseh ghaj chenta' an lalDanta' Daq Daq the forefront vo' the puH vo' Canaan, Daq the region about the Jordan, Daq the retlh vetlh pertains Daq the puqpu' vo' Israel.”",
        12: "ghorgh the puqpu' vo' Israel Qoyta' vo' 'oH, the Hoch tay' ghotpu' vo' the puqpu' vo' Israel boSta' themselves tay' Daq Shiloh, Daq jaH Dung Daq chaH Daq veS.",
        13: "The puqpu' vo' Israel ngeHta' Daq the puqpu' vo' Reuben, je Daq the puqpu' vo' Gad, je Daq the bID- tuq vo' Manasseh, Daq the puH vo' Gilead, Phinehas the puqloD vo' Eleazar the lalDan vumwI',",
        14: "je tlhej ghaH wa'maH joHHom, wa' joHHom vo' a fathers' tuq vaD each vo' the tuqpu' vo' Israel; je chaH were Hoch vo' chaH nach vo' chaj fathers' juHmey among the SaDmey vo' Israel.",
        15: "chaH ghoSta' Daq the puqpu' vo' Reuben, je Daq the puqpu' vo' Gad, je Daq the bID- tuq vo' Manasseh, Daq the puH vo' Gilead, je chaH jatlhta' tlhej chaH, ja'ta',",
        16: "“Thus jatlhtaH the Hoch tay' ghotpu' vo' joH'a', ‘nuq trespass ghaH vam vetlh SoH ghaj committed Daq the joH'a' vo' Israel, Daq tlhe' DoH vam jaj vo' following joH'a', Daq vetlh SoH ghaj chenta' SoH an lalDanta' Daq, Daq lotlh vam jaj Daq joH'a'?",
        17: "ghaH the He'taHghach vo' Peor too mach vaD maH, vo' nuq maH ghaj ghobe' cleansed ourselves Daq vam jaj, although pa' ghoSta' a rop'a' Daq the tay' ghotpu' vo' joH'a',",
        18: "vetlh SoH must tlhe' DoH vam jaj vo' following joH'a'? 'oH DichDaq taH, leghtaH vetlh SoH lotlh DaHjaj Daq joH'a', vetlh wa'leS ghaH DichDaq taH angry tlhej the Hoch tay' ghotpu' vo' Israel.",
        19: "However, chugh the puH vo' lIj possession ghaH Say'Ha', vaj juS Dung Daq the puH vo' the possession vo' joH'a', Daq nuq joH'a' tabernacle yIntaH, je tlhap possession among maH; 'ach yImev lotlh Daq joH'a', ghobe' lotlh Daq maH, Daq building an lalDanta' Daq latlh than the lalDanta' Daq vo' joH'a' maj joH'a'.",
        20: "ta'be' Achan the puqloD vo' Zerah commit a trespass Daq the devoted Doch, je QeHpu' pumta' Daq Hoch the tay' ghotpu' vo' Israel? vetlh loD ta'be' chIlqu' mob Daq Daj He'taHghach.'”",
        21: "vaj the puqpu' vo' Reuben je the puqpu' vo' Gad je the bID- tuq vo' Manasseh jangta', je jatlhta' Daq the nachDu' vo' the SaDmey vo' Israel,",
        22: "“The HoS wa', joH'a', joH'a', the HoS wa', joH'a', joH'a', ghaH SovtaH; je Israel DIchDaq Sov: chugh 'oH ghaHta' Daq rebellion, joq chugh Daq trespass Daq joH'a' (yImev toD maH vam jaj),",
        23: "vetlh maH ghaj chenta' maH an lalDanta' Daq Daq tlhe' DoH vo' following joH'a'; joq chugh Daq nob meQqu'pu' cha'nob joq 'uQ cha'nob, joq chugh Daq nob nobmey vo' roj nobmey, chaw' joH'a' himself require 'oH.",
        24: "“chugh maH ghaj ghobe' pa' vo' concern ta'pu' vam, je vaD a meq, ja'ta', ‘Daq poH Daq ghoS lIj puqpu' might jatlh Daq maj puqpu', ja'ta', “nuq ghaj SoH Daq ta' tlhej joH'a', the joH'a' vo' Israel?",
        25: "vaD joH'a' ghajtaH chenmoHta' the Jordan a veH joj maH je SoH, SoH puqpu' vo' Reuben je puqpu' vo' Gad. SoH ghaj ghobe' portion Daq joH'a'.”' vaj lIj puqpu' might chenmoH maj puqpu' mev vo' fearing joH'a'.",
        26: "“vaj maH ja'ta', ‘Let's DaH ghuH Daq chen ourselves an lalDanta' Daq, ghobe' vaD meQqu'pu' cha'nob, ghobe' vaD sacrifice;",
        27: "'ach 'oH DichDaq taH a witness joj maH je SoH, je joj maj DISmey after maH, vetlh maH may perform the toy'taHghach vo' joH'a' qaSpa' ghaH tlhej maj meQqu'pu' nobmey, tlhej maj nobmey, je tlhej maj roj nobmey;' vetlh lIj puqpu' may ghobe' ja' maj puqpu' Daq poH Daq ghoS, ‘SoH ghaj ghobe' portion Daq joH'a'.'",
        28: "“vaj maH ja'ta', ‘'oH DIchDaq taH, ghorgh chaH ja' maH joq maj DISmey vam Daq poH Daq ghoS, vetlh maH DIchDaq jatlh, “yIlegh the pattern vo' the lalDanta' Daq vo' joH'a', nuq maj vavpu' chenmoHta', ghobe' vaD meQqu'pu' cha'nob, ghobe' vaD sacrifice; 'ach 'oH ghaH a witness joj maH je SoH.”'",
        29: "“Hop taH 'oH vo' maH vetlh maH should lotlh Daq joH'a', je tlhe' DoH vam jaj vo' following joH'a', Daq chen an lalDanta' Daq vaD meQqu'pu' cha'nob, vaD 'uQ cha'nob, joq vaD sacrifice, je the lalDanta' Daq vo' joH'a' maj joH'a' vetlh ghaH qaSpa' Daj tabernacle!”",
        30: "ghorgh Phinehas the lalDan vumwI', je the joHHom vo' the tay' ghotpu', 'ach the nachDu' vo' the SaDmey vo' Israel vetlh were tlhej ghaH, Qoyta' the mu'mey vetlh the puqpu' vo' Reuben je the puqpu' vo' Gad je the puqpu' vo' Manasseh jatlhta', 'oH pleased chaH QaQ.",
        31: "Phinehas the puqloD vo' Eleazar the lalDan vumwI' ja'ta' Daq the puqpu' vo' Reuben, Daq the puqpu' vo' Gad, je Daq the puqpu' vo' Manasseh, “DaHjaj maH Sov vetlh joH'a' ghaH Daq the midst vo' maH, because SoH ghaj ghobe' committed vam trespass Daq joH'a'. DaH SoH ghaj toDta' the puqpu' vo' Israel pa' vo' the ghop vo' joH'a'.”",
        32: "Phinehas the puqloD vo' Eleazar the lalDan vumwI', je the joHHom, cheghta' vo' the puqpu' vo' Reuben, je vo' the puqpu' vo' Gad, pa' vo' the puH vo' Gilead, Daq the puH vo' Canaan, Daq the puqpu' vo' Israel, je qempu' chaH mu' again.",
        33: "The Doch pleased the puqpu' vo' Israel; je the puqpu' vo' Israel ghurtaH joH'a', je jatlhta' ghobe' latlh vo' ghoS Dung Daq chaH Daq veS, Daq Qaw' the puH Daq nuq the puqpu' vo' Reuben je the puqpu' vo' Gad yInta'.",
        34: "The puqpu' vo' Reuben je the puqpu' vo' Gad named the lalDanta' Daq “A Witness joj maH vetlh joH'a' ghaH joH'a'.”",
    },
    23: {
        1: "'oH qaSta' after law' jajmey, ghorgh joH'a' ghajta' nobpu' leS Daq Israel vo' chaj jaghpu' Hoch around, je Joshua ghaHta' qan je QaQ advanced Daq DISmey,",
        2: "vetlh Joshua ja' vaD Hoch Israel, vaD chaj quppu' je vaD chaj nachDu', je vaD chaj judges je vaD chaj officers, je ja'ta' Daq chaH, “jIH 'oH qan je QaQ advanced Daq DISmey.",
        3: "SoH ghaj leghpu' Hoch vetlh joH'a' lIj joH'a' ghajtaH ta'pu' Daq Hoch Dochvammey tuqpu' because vo' SoH; vaD 'oH ghaH joH'a' lIj joH'a' 'Iv ghajtaH Suvta' vaD SoH.",
        4: "yIlegh, jIH ghaj allotted Daq SoH Dochvammey tuqpu' vetlh remain, Daq taH an inheritance vaD lIj tuqpu', vo' the Jordan, tlhej Hoch the tuqpu' vetlh jIH ghaj pe' litHa', 'ach Daq the Dun biQ'a' toward the ghoS bIng vo' the pemHov.",
        5: "joH'a' lIj joH'a' DichDaq thrust chaH pa' vo' qaSpa' SoH, je drive chaH vo' pa' vo' lIj leghpu'. SoH DIchDaq ghaj chaj puH, as joH'a' lIj joH'a' jatlhta' Daq SoH.",
        6: "“vaj taH very courageous Daq pol je Daq ta' Hoch vetlh ghaH ghItlhta' Daq the paq vo' the chut vo' Moses, vetlh SoH ghobe' tlhe' aside vo' 'oH Daq the nIH ghop joq Daq the poS;",
        7: "vetlh SoH ghobe' ghoS among Dochvammey tuqpu', Dochvammey vetlh remain among SoH; ghobe' chenmoH mention vo' the pong vo' chaj Qunpu', ghobe' cause Daq swear Sum chaH, ghobe' toy' chaH, ghobe' bow bIng tlhIH'egh Daq chaH;",
        8: "'ach 'uch fast Daq joH'a' lIj joH'a', as SoH ghaj ta'pu' Daq vam jaj.",
        9: "“vaD joH'a' ghajtaH driven Dun je HoS tuqpu' pa' vo' qaSpa' SoH. 'ach as vaD SoH, ghobe' loD ghajtaH Qampu' qaSpa' SoH Daq vam jaj.",
        10: "wa' loD vo' SoH DIchDaq chase a SaD; vaD 'oH ghaH joH'a' lIj joH'a' 'Iv fights vaD SoH, as ghaH jatlhta' Daq SoH.",
        11: "tlhap QaQ heed vaj Daq tlhIH'egh, vetlh SoH muSHa' joH'a' lIj joH'a'.",
        12: "“'ach chugh SoH ta' Daq Hoch jaH DoH, je 'uch fast Daq the chuv vo' Dochvammey tuqpu', 'ach Dochvammey 'Iv remain among SoH, je chenmoH marriages tlhej chaH, je jaH Daq Daq chaH, je chaH Daq SoH;",
        13: "Sov vaD a certainty vetlh joH'a' lIj joH'a' DichDaq ghobe' longer drive Dochvammey tuqpu' vo' pa' vo' lIj leghpu'; 'ach chaH DIchDaq taH a tojta'ghach je a trap Daq SoH, a scourge Daq lIj sides, je thorns Daq lIj mInDu', until SoH chIlqu' vo' litHa' vam QaQ puH nuq joH'a' lIj joH'a' ghajtaH nobpu' SoH.",
        14: "“yIlegh, DaHjaj jIH 'oH ghoS the way vo' Hoch the tera'. SoH Sov Daq Hoch lIj tIQDu' je Daq Hoch lIj qa'pu' vetlh ghobe' wa' Doch ghajtaH failed vo' Hoch the QaQ Dochmey nuq joH'a' lIj joH'a' jatlhta' concerning SoH. Hoch ghaj qaSta' Daq SoH. ghobe' wa' Doch ghajtaH failed vo' 'oH.",
        15: "'oH DIchDaq qaS vetlh as Hoch the QaQ Dochmey ghaj ghoS Daq SoH vo' nuq joH'a' lIj joH'a' jatlhta' Daq SoH, vaj joH'a' DichDaq qem Daq SoH Hoch the mIghtaHghach Dochmey, until ghaH ghajtaH Qaw'ta' SoH vo' litHa' vam QaQ puH nuq joH'a' lIj joH'a' ghajtaH nobpu' SoH,",
        16: "ghorgh SoH disobey the lay' vo' joH'a' lIj joH'a', nuq ghaH ra'ta' SoH, je jaH je toy' latlh Qunpu', je bow bIng tlhIH'egh Daq chaH. vaj the QeH vo' joH'a' DichDaq taH kindled Daq SoH, je SoH DichDaq chIlqu' quickly vo' litHa' the QaQ puH nuq ghaH ghajtaH nobpu' Daq SoH.”",
    },
    24: {
        1: "Joshua boSta' Hoch the tuqpu' vo' Israel Daq Shechem, je ja' vaD the quppu' vo' Israel, vaD chaj nachDu', vaD chaj judges, je vaD chaj officers; je chaH presented themselves qaSpa' joH'a'.",
        2: "Joshua ja'ta' Daq Hoch the ghotpu, “Thus jatlhtaH joH'a', the joH'a' vo' Israel, ‘lIj vavpu' yInta' vo' qan poH beyond the bIQtIQ, 'ach Terah, the vav vo' Abraham, je the vav vo' Nahor: je chaH served latlh Qunpu'.",
        3: "jIH tlhapta' lIj vav Abraham vo' beyond the bIQtIQ, je led ghaH throughout Hoch the puH vo' Canaan, je multiplied Daj tIr, je nobta' ghaH Isaac.",
        4: "jIH nobta' Daq Isaac Jacob je Esau: je jIH nobta' Daq Esau Mount Seir, Daq ghaj 'oH. Jacob je Daj puqpu' mejta' bIng Daq Egypt.",
        5: "“‘jIH ngeHta' Moses je Aaron, je jIH plagued Egypt, according Daq vetlh nuq jIH ta'ta' Daq its midst: je afterward jIH qempu' SoH pa'.",
        6: "jIH qempu' lIj vavpu' pa' vo' Egypt: je SoH ghoSta' Daq the biQ'a'. The Egyptians pursued after lIj vavpu' tlhej Dujmey je tlhej horsemen Daq the Doq biQ'a' { Note: joq, biQ'a' vo' Reeds }.",
        7: "ghorgh chaH SaQta' pa' Daq joH'a', ghaH lan HurghtaHghach joj SoH je the Egyptians, je qempu' the biQ'a' Daq chaH, je covered chaH; je lIj mInDu' leghta' nuq jIH ta'ta' Daq Egypt: je SoH yInta' Daq the ngem law' jajmey.",
        8: "“‘jIH qempu' SoH Daq the puH vo' the Amorites, vetlh yInta' beyond the Jordan: je chaH Suvta' tlhej SoH; je jIH nobta' chaH Daq lIj ghop. SoH possessed chaj puH; je jIH Qaw'ta' chaH vo' qaSpa' SoH.",
        9: "vaj Balak the puqloD vo' Zippor, joH vo' Moab, Hu' je Suvta' Daq Israel. ghaH ngeHta' je ja' Balaam the puqloD vo' Beor Daq mu'qaD SoH;",
        10: "'ach jIH would ghobe' 'Ij Daq Balaam; vaj ghaH ghurtaH SoH vIHHa'. vaj jIH toDta' SoH pa' vo' Daj ghop.",
        11: "“‘SoH mejta' Dung the Jordan, je ghoSta' Daq Jericho. The loDpu' vo' Jericho Suvta' Daq SoH, the Amorite, the Perizzite, the Canaanite, the Hittite, the Girgashite, the Hivite, je the Jebusite; je jIH toDta' chaH Daq lIj ghop.",
        12: "jIH ngeHta' the hornet qaSpa' SoH, nuq drove chaH pa' vo' qaSpa' SoH, 'ach the cha' joHpu' vo' the Amorites; ghobe' tlhej lIj 'etlh, ghobe' tlhej lIj bow.",
        13: "jIH nobta' SoH a puH whereon SoH ghajta' ghobe' labored, je vengmey nuq SoH ta'be' chen, je SoH yIn Daq chaH. SoH Sop vo' vineyards je olive groves nuq SoH ta'be' plant.'",
        14: "“DaH vaj taHvIp joH'a', je toy' ghaH Daq 'IltaH je Daq vIt. lan DoH the Qunpu' nuq lIj vavpu' served beyond the bIQtIQ, Daq Egypt; je toy' joH'a'.",
        15: "chugh 'oH seems mIghtaHghach Daq SoH Daq toy' joH'a', choose vam jaj 'Iv SoH DichDaq toy'; whether the Qunpu' nuq lIj vavpu' served vetlh were beyond the bIQtIQ, joq the Qunpu' vo' the Amorites, Daq 'Iv puH SoH yIn: 'ach as vaD jIH je wIj tuq, maH DichDaq toy' joH'a'.”",
        16: "The ghotpu jangta', “Hop taH 'oH vo' maH vetlh maH should lon joH'a', Daq toy' latlh Qunpu';",
        17: "vaD 'oH ghaH joH'a' maj joH'a' 'Iv qempu' maH je maj vavpu' Dung pa' vo' the puH vo' Egypt, vo' the tuq vo' bondage, je 'Iv ta'ta' chaH Dun signs Daq maj leghpu', je polta' maH Daq Hoch the way Daq nuq maH mejta', je among Hoch the ghotpu' vegh the midst vo' 'Iv maH juSta'.",
        18: "joH'a' drove pa' vo' qaSpa' maH Hoch the ghotpu', 'ach the Amorites 'Iv yInta' Daq the puH. vaj maH je DichDaq toy' joH'a'; vaD ghaH ghaH maj joH'a'.”",
        19: "Joshua ja'ta' Daq the ghotpu, “SoH ta'laHbe' toy' joH'a'; vaD ghaH ghaH a le' joH'a'. ghaH ghaH a jealous joH'a'. ghaH DichDaq ghobe' forgive lIj disobedience ghobe' lIj yemmey.",
        20: "chugh SoH lon joH'a', je toy' foreign Qunpu', vaj ghaH DichDaq tlhe' je ta' SoH mIghtaHghach, je consume SoH, after ghaH ghajtaH ta'pu' SoH QaQ.”",
        21: "The ghotpu ja'ta' Daq Joshua, “ghobe'; 'ach maH DichDaq toy' joH'a'.”",
        22: "Joshua ja'ta' Daq the ghotpu, “SoH 'oH witnesses Daq tlhIH'egh vetlh SoH ghaj wIvpu' joH'a' tlhIH'egh, Daq toy' ghaH.” chaH ja'ta', “maH 'oH witnesses.”",
        23: "“DaH vaj lan DoH the foreign Qunpu' nuq 'oH among SoH, je incline lIj tIq Daq joH'a', the joH'a' vo' Israel.”",
        24: "The ghotpu ja'ta' Daq Joshua, “maH DichDaq toy' joH'a' maj joH'a', je maH DichDaq 'Ij Daq Daj ghogh.”",
        25: "vaj Joshua chenmoHta' a lay' tlhej the ghotpu vetlh jaj, je chenmoHta' vaD chaH a statute je an ordinance Daq Shechem.",
        26: "Joshua wrote Dochvammey mu'mey Daq the paq vo' the chut vo' joH'a'; je ghaH tlhapta' a Dun nagh, je cher 'oH Dung pa' bIng the Sor'a' vetlh ghaHta' Sum the Daq QaD vo' joH'a'.",
        27: "Joshua ja'ta' Daq Hoch the ghotpu, “yIlegh, vam nagh DIchDaq taH a witness Daq maH; vaD 'oH ghajtaH Qoyta' Hoch the mu'mey vo' joH'a' nuq ghaH jatlhta' Daq maH. 'oH DIchDaq taH vaj a witness Daq SoH, lest SoH deny lIj joH'a'.”",
        28: "vaj Joshua ngeHta' the ghotpu DoH, Hoch loD Daq Daj inheritance.",
        29: "'oH qaSta' after Dochvammey Dochmey, vetlh Joshua the puqloD vo' Nun, the toy'wI' vo' joH'a', Heghta', taH wa' vatlh je wa'maH DISmey qan.",
        30: "chaH buried ghaH Daq the veH vo' Daj inheritance Daq Timnathserah, nuq ghaH Daq the HuD Hatlh vo' Ephraim, Daq the pemHov nIH vo' the HuD vo' Gaash.",
        31: "Israel served joH'a' Hoch the jajmey vo' Joshua, je Hoch the jajmey vo' the quppu' 'Iv outlived Joshua, je ghajta' Sovta' Hoch the vum vo' joH'a', vetlh ghaH ghajta' worked vaD Israel.",
        32: "chaH buried the HomDu' vo' Joseph, nuq the puqpu' vo' Israel qempu' Dung pa' vo' Egypt, Daq Shechem, Daq the parcel vo' yav nuq Jacob je'ta' vo' the puqloDpu' vo' Hamor the vav vo' Shechem vaD a vatlh pieces vo' Huch. chaH mojta' the inheritance vo' the puqpu' vo' Joseph.",
        33: "Eleazar the puqloD vo' Aaron Heghta'. chaH buried ghaH Daq the HuD vo' Phinehas Daj puqloD, nuq ghaHta' nobpu' ghaH Daq the HuD Hatlh vo' Ephraim.",
    },
}
